/* 0x800175b8: In-place scale vector by ratio ratio/len using GTE gpl0. Computes (ratio << 12)/len then multiplies each component by it with 12-bit fixed-point. Heavily used by Spyro physics/movement. */
void ScaleVector3ByRatio(int *vec, int len, int ratio);

/* 0x80017614: In-place scale of int[3] vector by IR0 fixed-point factor (gte_gpl0 with MAC=0), then arithmetic right-shift each component by shift. Used in physics for velocity damping. */
void ScaleVector3Shifted(int *vec, int num, int shift);

/* 0x800176a0: In-place left-shift of an int[3] vector by n bits. Sibling of RShiftVector3. */
void LShiftVector3(int *v, int n);

/* 0x800176c8: Arithmetic right-shifts each of the 3 signed ints at *v by (n & 0x1f). Used for fixed-point precision conversion in the actor draw path. */
void RShiftVector3(int *v, int n);

void ZeroVector(int *vec);

void CopyVector(int *dst, int *src);

void AddVector(int *dst, int *a, int *b);

void SubtractVector(int *dst, int *a, int *b);

/* 0x800177c0: Scale VECTOR by IR0 fixed-point factor (gte_gpl0 with MAC=0); store saturated IR1/IR2/IR3 packed via stlvnl0 into long*. Sibling of LerpVectorGTE but single-input + saturated short output. */
void ScaleVector3Sat(int *dst, int *src, int scale);

/* 0x80017894: Linear interpolation between two VECTOR points using GTE gpl0. t is the 0x1000-fixed blend ratio (0=b, 0x1000=a). Output written to dst. */
void LerpVectorGTE(int *dst, int *a, int *b, int t);

/* 0x80017908: Absolute shortest delta between two 8-bit angles. Returns |(a-b) wrapped to [-0x80, 0x80)| in [0, 0x80]. */
int AbsAngleDelta8(int a, int b);

/* 0x80017928: Absolute shortest delta between two 12-bit angles (0x1000 = 360deg). Returns |(a-b) wrapped to [-0x800, 0x800)| in [0, 0x800]. */
int AbsAngleDelta12(int a, int b);

/* 0x80017948: Signed shortest delta between two 8-bit angles. Returns (a-b) wrapped to [-0x80, 0x80). */
int SignedAngleDelta8(int a, int b);

/* 0x8001796c: Signed shortest delta between two 12-bit angles (0x1000 = 360deg). Returns (a-b) wrapped to [-0x800, 0x800). */
int SignedAngleDelta12(int a, int b);

/* 0x80017990: Octagonal 2D distance approximation: max(|dx|,|dy|) + 3/8 * min(|dx|,|dy|). Faster than sqrt for collision broad-phase checks. */
int ApproxDist2D(int *a, int *b);

/* 0x800179f0: Step 8-bit angle cur toward target target by step step, with deadzone lim. Returns target unchanged if within deadzone. */
int ApproachAngle8(int target, int cur, int step, int lim);

/* 0x80017a38: Integer square root via GTE LZCS-normalize + LUT (g_anSqrtLUT) + reciprocal-shift. Output is in 12.4 fixed-point (caller >>0xc to get integer)? Returns approx sqrt(n). */
int IntegerSqrt(int n);

/* 0x80017aa4: Projects a world-space point to screen XY + depth via the GTE rotation matrix at g_anWorldToCameraRotMtx / base at g_anCameraPos — unscaled variant of ProjectWorldPointGTE (no input right-shift or output left-shift). Writes screen.x, screen.y, MAC3 to out[0..2]. All known callers live in the camera band. */
void ProjectWorldPointGTEUnscaled(int *out, int *pos);

/* 0x80017b48: Projects a world-space point to screen XY + depth via the GTE rotation matrix at g_anWorldToCameraRotMtx and base point at g_anCameraPos. src = source world point; shift = right-shift on input (precision selector); writes screen.x, screen.y, MAC3<<shift to dst[0..2]. */
void ProjectWorldPointGTE(int *dst, int *src, unsigned int shift);

/* 0x80017c4c: Sign-extend a short[3] vector (SVECTOR) into an int[3] (VECTOR). PSX SDK-style helper. */
void SVectorToVector(int *dst, short *src);

/* 0x80017c68: Truncate an int[3] vector (VECTOR) into a short[3] (SVECTOR). PSX SDK-style helper. */
void VectorToSVector(short *dst, int *src);

/* 0x80017cb8: Unpacks a packed collision-triangle from the world's triangle table at *(g_pWorldCollisionHeader+0x10) into a 9-int output buffer (3 vertices × 3 coords). Table entry size = 12 bytes (3 uint32 packed coord-triplets). Per axis (X, Y, Z): low 14 bits = vertex 0's coord (shifted left 4 to recover world units). Then v1 = v0 + signed-9-bit delta (X/Y) or unsigned-8-bit delta (Z); v2 same scheme with deltas at bits 23..31 (X/Y) or 24..31 (Z). All outputs scaled by 16. Output layout: [v0.X, v0.Y, v0.Z, v1.X, v1.Y, v1.Z, v2.X, v2.Y, v2.Z]. The asymmetric encoding (Z always-positive deltas) reflects that these are upward-facing collision triangles (floor + slope geometry). Callers: ProbeSpyroGroundContact + AverageSpyroPlatformMotion (M07 — collision query fetches a candidate triangle's vertices for ray test). */
void UnpackWorldCollisionTri(int chunk, int *verts);

/* 0x80017e54: GTE depth-cue color computation. Interpolates the input RGB (base, packed 24-bit) toward a far color (color, packed as three 12-bit channels: R=bits 0-7, G=bits 4-15 masked, B=bits 12-23 masked) by IR0 factor (t, 0..0x1000). Returns the depth-cued RGB color in the low 32 bits, with the far-blue channel echoed in bits 32-39 (probably an artifact of the caller's unpack pattern at ActorCutscene_Draw where it stores all three output bytes into the backdrop color slots). Implementation: gte_ldRGB + gte_ldIR0 + gte_ldfcdir + gte_dpcs + gte_stRGB2. */
unsigned int ComputeDepthCuedColor(unsigned int base, unsigned int color, int t);

/* 0x80017e98: Convert a buffer of RGB15 pixels (two per 32-bit word) to packed 8-bit luminance bytes. Luma = (4*R + G*(1/16+1/32) + B/1024) >> 3. count = end-offset in bytes. */
void ConvertRGB15ToLuma8(void *buf, int count);

/* 0x80017f24: RLE color-run bias applier. Each run header word encodes byte-offset (low 17 bits, *4-aligned) and count (bits 17..30); negative header = terminator. For each 32-bit RGBA packet, adds bias to each byte saturating at 0. Called once from Initialize, likely tinting boot CLUT/HUD palette. */
void AddBiasToColorRuns(void *dst, void *src, int bias);

/* 0x80017fe4: Emits a glyph-sprite chain for a string: per non-space byte allocates a 0x58-byte slot at g_pSpriteRecordWriteCursor (queue tail, grows down), maps '0'-'9' and 'A'-'Z' (+ a few specials: '/', '?', '%', '^', '+') to font tile indices, copies the cursor position from pPen and advances *pPen by nAdvance between glyphs. Sibling of BuildTextSprites. */
void *BuildTextSpriteChain(unsigned char *pszText, int *pPen, int nAdvance, int nPalette);

/* 0x800181ac: Queues one glyph sprite record per non-space character of `text` at g_pSpriteRecordWriteCursor, advancing the pen from *pos by the glyph width attr[0] (digits / '!' / '?' by `spacing`, spaces by 3/4 width). Returns the cursor. */
void *BuildTextSprites(char *text, int *pos, int *attr, int spacing, int flags);

/* 0x8001844c: Emits a 2-point gradient line (LineG2) into the OT. Each endpoint's RGB is tinted by the angular distance between its screen-relative angle (vs (256,120)) and a reference angle in g_nLightSweepAngle — radial-light effect for menu borders. Called by Gamestate02_03_06_Draw and DrawShadedMenuBox. */
void EmitRadialShadedLine(int x0, int y0, int x1, int y1);

/* 0x80018534: Pushes a sprite16 onto the front of the sprite queue (g_pSpriteRecordWriteCursor bumps down 0x58 bytes). Gated by (frame & 0x1f) < 0x10 so the sprite blinks for half of every 32-frame cycle; tile < 2 selects tile U=0 vs U=0x80. Used as a selection marker in Gamestate02_03_06_Draw. */
void EnqueueBlinkingMarkerSprite(int *pos, int frame, int tile);

/* 0x8001860c: Draws a menu rectangle: semi-transparent POLY_F4 fill at (left,top)..(right,bottom) plus four EmitRadialShadedLine borders. Called by SaveLoadMenu_Draw. */
void DrawShadedMenuBox(int left, int right, int top, int bottom);

/* 0x80018728: Draws the dragon-rescue cutscene banner: "RESCUED" (g_szUiRescued) + the freed dragon's name (g_apDragonNames[g_pDragonRescueSourceActor->id at +0x38]) as two right-aligned BuildTextSpriteChain labels (anchors x=176/x=336), per-glyph alpha pulsed by the sine LUT off g_nDragonRescueSecondaryTimer. Called by DragonRescue_Draw. (ex-DrawWorldMapLevelLabel, corrected sweep 40.) */
void DrawDragonRescuedBanner(void);

/* 0x80018880: Refills the null-terminated sprite/HUD primitive request queue at g_apSpritePrimQueue by carving the remainder of the primitive buffer (g_pSpriteRecordWriteCursor up to g_pSpriteRecordBufferTop) into 0x58 (88-byte) chunks and appending each as a queue entry. Called near end of GamestateDraw before DrawSync. */
void EnqueuePendingSpritePrims(void);

/* 0x80018908: Builds the "DEMO MODE" text overlay via BuildTextSprites, then phase-pulses each glyph's alpha using the sine LUT at g_anCosineLut indexed by g_nVblankTickCount (animation phase). Hands the resulting 0x58-byte sprite records into the request queue via EnqueuePendingSpritePrims. */
void DrawDemoModeOverlay(void);

/* 0x800189f0: Emits semi-transparent POLY_G4 ribbon segments between consecutive history points of each active "trail" (Spyro flight/glide/charge wake). g_apMotionTrailSlices holds per-trail point arrays; g_anMotionTrailSliceCounts holds per-trail point counts; g_nMotionTrailRibbonCount is the active trail count. Perpendicular width is divided by point depth (piVar5[5]) and colored on a falloff curve from head to tail. Resets g_nMotionTrailRibbonCount to 0 on exit. */
void DrawMotionTrailRibbons(void);

/* 0x80018f30: Draws two stacked black POLY_F4 cinematic bars (top y=0..h, bottom y=240-h..240) where h = g_nLetterboxBarHeight animates 0..0x16 driven by g_nCinematicActive. The "letterbox close" / "open" animation seen during cutscenes and gameplay-blocked transitions. Submits both bars via AddPrimToOT. */
void DrawCinematicLetterbox(void);

/* 0x800190d4: Submits a semi-transparent fullscreen POLY_F4 (rect (0,8)-(512,232)) of color (r,g,b) into the active OT depth slot. Allocates from the primitive buffer at g_pPrimBufferWriteCursor; chains via AddPrimToOT. Used for fade/tint overlays (the g_nScreenFadeLevel fade, the dragon-rescue flash, the scripted-cutscene fade). */
void DrawFullscreenTint(int slot, int r, int g, int b);

/* 0x8001919c: Emits a textured POLY_FT4 quad: rect (x,y,w,h)=rect[0..3] shorts, UV+CLUT=uv[0..1], RGB color=rgb[0..2] or default 0x80,0x80,0x80. Calls AddPrimToOT and advances g_pPrimBufferWriteCursor by 0x28 bytes. */
void EmitTexturedQuad(short *rect, unsigned int *uv, unsigned int *rgb);

/* 0x80019300: Queues the in-level HUD (formerly EnqueueLoadingScreenSprites). Outside flight levels it appends to g_apSpritePrimQueue whichever HUD counters are showing: the gem-counter icons and the rolling gem digits (sprintf + BuildTextSpriteChain, each digit bobbing), the three dragon records, the three life records and the level-egg record. Always (flight levels too) it draws the Sparx-food butterflies (swept cosine shade) and the egg icons (cycling nine UV pairs) as textured quads. Called from GamestateDraw and the pause/inventory draw. */
void EnqueueHudSprites(void);

/* 0x80019698: Mid-frame scene composer — sequences the actor/sprite/effect passes of one frame: BuildActorDrawList, FillWord(&g_pOtDepthBinHead0,0,0x900) OT clear, EmitActorDrawList, BuildSecondaryActorDrawList + EmitSecondaryActorPrimitives, RasterizeSpritePrimQueue, DrawEntityDirectionalSpikes; unless g_nSpyroDrawSuppressed: RasterizeSpyroModel (Spyro) + DrawSpyroDropShadow; if g_bSpyroFlameActive: DrawSpyroFlameTrails. Returns DrawWorldParticleEmitters() chained out. */
void ComposeFrameScene(void);

/* 0x8001973c: Renders the level-entry/exit overlay used by Gamestate01/09 (level transition). Builds the primary banner ("RETURNING HOME...", "ENTERING %s...", or "CONFRONTING %s..." for boss levels — level 4 of the first five worlds and LEVEL_GNASTY_GNORC) from g_apLevelNameStrings indexed by world/level. From phase 0x40 (post-level results) also emits "TREASURE FOUND" / "TOTAL TREASURE" with the count animated via g_szFmtPercentD: found = g_anLevelGemsCollected[g_nPrevLevelIndex] - g_nLevelGemsAtEntry, interpolated over the gem fly-in (duration 2*(g_nGemTallyIconCount+1) clamped 0x40), plus one gem icon per alive g_pGemTallyParticleRecords record with sprite U from g_abGemTallyIconUvTable. All slide/fade animation is driven by g_nLevelTransitionPhase; panel hold ends at g_nGemTallyHoldEndPhase. Clears g_apSpritePrimQueue[0], then EnqueuePendingSpritePrims + RasterizeSpritePrimQueue to flush directly. */
void DrawLevelTransitionOverlay(void);

/* 0x8001a050: Draws Gamestate 1 (boot/early splash) and 9 (sibling): clears OT, draws a rotating 3D model (via EmitStaticActorMeshList with matrix built from g_nCameraEulerRoll/e1e/e20 rotation angles), copies background RGB from g_dwWorldFogColor into draw-env clear color, then VSync/frame submit. g_nLevelIntroParallaxCountdown is an animation phase counter that decrements by 2 each frame; when 0, uses identity matrix. Active model render only when g_nWorldRenderMeshChunkCount != 0. */
void LevelTransition_Draw(void);

/* 0x8001a40c: Draw for gamestates 2 (pause menu), 3 (inventory sub-menu), 6 (overlay-rendered dialog). g_nMenuDrawFrames==0 (entry frame): renders one full gameplay scene (BuildRenderEntityLists/ComposeFrameScene/RasterizeEmitList/DrawPortalsAndStaticActors), then builds the frozen backdrop — StoreImage's the frame, ConvertRGB15ToLuma8 packs 4 strips to 8bpp luma in g_pRenderScratchRegionBase, reloads them at VRAM x=0x200 and loads g_anMenuBackdropGrayClut to (0x200,0xe0) (clut id 0x3820). Later frames: draws 4 textured quads of the gray backdrop + menu UI. State 2: PAUSED box (substate 0 = CONTINUE/OPTIONS/INVENTORY/QUIT-or-EXIT-LEVEL, 1 = options incl. DualShock-gated VIBRATION, 2 = QUIT GAME? YES/NO); cursor glyphs wave via g_anSineLut. State 3: inventory — header gem/dragon/egg tallies + per-level rows of the g_nSubMenuCursor world (only rows with g_abLevelVisitedFlag set), scroll arrows gated by the +/-6 virtual bases of g_abLevelVisitedFlag. State 6: backdrop + overlay-enqueued sprites only. Ends with sprite-queue rasterize, 2-vblank pacing (g_nVsyncFramePaceAnchor), increments g_nMenuDrawFrames. */
void Gamestate02_03_06_Draw(void);

/* 0x8001c694: Draws gamestate 0xA (pause -> world-map transition, set by BeginPauseToMenuTransition). g_nMenuDrawFrames==0 phase: re-darkens the frozen gray backdrop by re-loading g_anMenuBackdropGrayClut SHIFTED — rect {x=0x200+g_nMenuTickFrames, y=0xe0, w=0x20-idleFrames} maps ramp[0..w] onto CLUT entries idle..31, so the bright end dims as the 0..32 idle counter runs — then draws the 4 backdrop quads (clut id 0x3820) into OT slot 0x3ff. ==1 phase: fog cross-fade — g_nFadeProgress=(0x20-idle)*0x80 through ComputeDepthCuedColor into the back DRAWENV r0/g0/b0 + EmitStaticActorMeshListFogged. Both phases: OT clear, RasterizeSpyroModel (Spyro), DrawOTag, 2-vblank pacing via g_nVsyncFramePaceAnchor. */
void MenuTransition_Draw(void);

/* 0x8001ca38: Draw routine for g_nGamestate == GS_RESPAWN or 5 (in-level / game-over). Two phases gated by g_nRespawnOrGameOverMode: mode 0: normal in-level frame. On frame 0 calls the full game render chain (BuildRenderEntityLists/19698/573c8/50bd0/2b9cc); subsequent frames flash a fade color via DrawFullscreenTint. mode 1: game-over sequence. After frame 0x3c, builds the "GAMEOVER" letter sprites (s_GAMEOVER_8006f304 / g_anGameOverLetterPosXY layout table), and after frame 0x1a5 also renders "PRESS START". g_nRespawnOrGameOverFrame is the per-mode frame counter that drives both fade timing and the GAMEOVER reveal animation. Tail is the standard PutDispEnv/PutDrawEnv/DrawOTag frame submit. */
void RespawnOrGameOver_Draw(void);

/* 0x8001cfdc: Draws Gamestate 8: the dragon-rescue overlay. Has 8 substates (0..7) driven by g_nDragonRescueSubstate: 0: full render chain (normal gameplay frame, fade-only effect). 1-4: composite render with partial OT buffers and dragon-statue sprites. 5-7: cutscene-only render with timed model placement. Uses g_nDragonRescueTimer for animation timing. */
void DragonRescue_Draw(void);

/* 0x8001d718: Draws Gamestate 0xB: SAVE / LOAD MENU. g_nSaveMenuMode == 1 enables UI render (else skip straight to gameplay underlay). g_nSaveMenuSubstate is the menu substate: 0: main menu (SAVE GAME / REPLAY DRAGON / CONTINUE) 1: 'NO SAVE FILE' (insert memory card) 2: 'SAVING...' 3: 'NO MEMORY CARD' 4: 'NO SAVE FILE' 5: 'SAVE ERROR' 6: 'SAVE FAILED' (RETRY/ABORT) 7: 'GAME SAVED' g_nSaveMenuCursor is the menu cursor index. g_nSaveSlotSelected selects SLOT 1 vs SLOT 2. g_nSaveMenuXOffset is an x-coordinate offset for menu placement. */
void SaveLoadMenu_Draw(void);

/* 0x8001e24c: Draw routine for g_nGamestate == GS_ACTOR_CUTSCENE (level-transition state). Renders the "ENTERING %s WORLD" / "ENTERING %s" title-card overlay using BuildTextSprites, then submits the frame. Active only when the 0xC substate g_nActorCutsceneSubstate is 4 or 5; otherwise dispatches to the function pointer at g_pfnActorCutsceneSubstateDraw. World/level names are looked up by g_nCurrentLevelId: worldIdx = id / 10 -> PTR_s_DRAGON_X_8006f7d0[worldIdx] levelIdx = id - worldIdx*4 -> PTR_s_PEACE_KEEPERS_8006f7d8[levelIdx] Tail (DrawSync/VSync/PutDispEnv/PutDrawEnv/DrawOTag) is the standard frame-submit sequence shared by every Gamestate*_Draw routine. */
void ActorCutscene_Draw(void);

/* 0x8001e6b8: Draws Gamestate 0xD when g_nTitleMode == TITLE_MODE_STORY_INTRO: 'story intro' splash that fades in/out one of three messages (selected by g_nTitleExitPath): 0: 'IN THE WORLD OF DRAGONS...' 1: 'THE ADVENTURE BEGINS...' / 'THE ADVENTURE CONTINUES...' (g_abLevelVisitedFlag picks variant) 2: 'ENTERING DEMO MODE...' g_nStoryIntroTimer is the per-message frame counter (used for fade alpha; animation starts when the value crosses the message-specific threshold). */
void StoryIntro_Draw(void);

/* 0x8001e9c8: Draws Gamestate 0xE: the scripted in-engine cutscene. Sets the clear color from the world fog color, draws the cutscene actors, RenderWorldChunks(-1) for the whole cutscene set, then EmitStaticActorMeshList(-1, camera view). Uses g_nScreenFadeLevel for the closing fade-to-black. */
void Cutscene_Draw(void);

/* 0x8001eb80: Draws Gamestate 0xF when g_nCreditsMode >= 99: post-credits 'RETURNING HOME...' message with animated text wave. Clears bg, builds text sprites for the message, then animates per-character brightness by stepping a 4-byte stride into g_anCosineLut (sin/intensity LUT) indexed by g_nReturningHomePhase (animation phase counter). */
void ReturningHome_Draw(void);

/* 0x8001ed5c: Per-frame draw dispatcher (partner of GamestateUpdate). Flips g_pActiveFrameDrawEnv between the two frame DBs, reloads g_pPrimBufferWriteCursor/g_pOtDepthBinArrayBase/g_pOtActiveDepthSlot from the DB tail (+0x70/74/78), clears g_nPrimBufferOverflowFlag, then for gamestate 0 runs the full scene pipeline (BuildRenderEntityLists -> ComposeFrameScene -> SetupFrameOT -> DrawPortalsAndStaticActors -> RasterizeEmitList + overlays), paces to >=2 vblanks via g_nVsyncFramePaceAnchor, PutDispEnv/PutDrawEnv, DrawOTag. Other states branch to per-state Draw functions; state 7 calls g_pfnGamestate7DrawHook. Writes g_dwWorldFogColor into both DRAWENVs' r0/g0/b0 each gameplay frame. */
void GamestateDraw(void);

/* 0x8001f158: First half of the actor render pipeline. Walks the actor reference array at g_pOtDepthBinHead0, frustum/depth-culls each record using the camera position (g_anCameraPos/dfc/e00) and bounding radius from the actor record, then writes per-visible-actor display records (14 ints each) to the draw list at g_anActorDrawList. Each record stores actor pointer, mesh ptr, texture-page ptr, world-to-screen rotation submatrix (lazily wobbled via the optional roll/pitch/yaw fields in g_anWorldToCameraRotMtx..e0), and clip-space position. Terminated by 0. */
void BuildActorDrawList(void);

/* 0x8001f798: Second half of the actor render pipeline. Walks BuildActorDrawList's output at g_anActorDrawList and, for each visible actor, runs the GTE per-vertex transform + lighting pass (rtps/intpl/nclip), emits POLY_F3/POLY_G3/POLY_FT4/POLY_GT4 primitives into the OT depth bins at g_pOtDepthBinHead0, and writes per-actor scratch (depth-cued colors at g_anActorDepthCuedVtxColor). Reads per-frame fog params at g_dwWorldFogColor and ambient/background colors via gte_ldRFC/gte_ldGFC/gte_ldBFC. Submits via per-bin insertion (not AddPrimToOT) for correct depth sort. */
void EmitActorDrawList(void);

/* 0x800208fc: Sibling of BuildActorDrawList. Walks the actor pointer table at g_apSecondaryDrawEntityList (terminated by NULL) — a different source than BuildActorDrawList's g_pOtDepthBinHead0 depth-bin list — performs frustum culling against bounds in g_anCameraPos/dfc/e00, then composes each actor's per-axis Euler rotation (packed in *(actor + 0x44)) onto the camera matrix g_anWorldToCameraRotMtx..de0 via GTE rtv0 + sine/cosine LUTs. Appends 0x38-byte entries (transform + matrix + back-pointer) to the visible-actor list at g_anActorDrawList. Writes the terminator 0 at the end. */
void BuildSecondaryActorDrawList(void);

/* 0x80020f34: Sibling of EmitActorDrawList. Walks the visible-actor list at g_anActorDrawList (filled by BuildActorDrawList + BuildSecondaryActorDrawList). For each entry, loads the per-actor 3x3 matrix and translation into the GTE, sets background depth via gte_ldbkdir for per-vertex lighting, and emits transformed mesh primitives to the scratch buffer at g_anOtPrimSaveList / the active prim buffer at g_pPrimBufferWriteCursor. Restores g_pPrimBufferWriteCursor on completion. */
void EmitSecondaryActorPrimitives(void);

/* 0x80022a2c: Walks the sprite/HUD request queue at g_apSpritePrimQueue (refilled by EnqueuePendingSpritePrims) and rasterizes each request. For each actor record: applies per-axis billboard rotations from `actor.flags` (gte_rtv0 for X/Y/Z roll/pitch/yaw bytes), runs the per-vertex GTE transform with optional Z-bias depth cueing, emits POLY_F3/POLY_F4/POLY_G4 primitives into the OT depth bins, and updates the per-bin head/tail pointers (g_pOtDepthBinHead0 / g_pOtDepthBinTail0) directly for depth-sorted insertion. Inserts a TPAGE/DRAWMODE command before the first run of primitives in a frame. */
void RasterizeSpritePrimQueue(void);

/* 0x80023ac4: Rasterizes Spyro's model (hand-written; formerly RasterizePairedActor). Its base register is the Spyro block (g_anSpyroWorldPos); the mesh and frame records come from g_apActorMeshTable indexed by Spyro's previous and current anim bytes (g_bSpyroAnimPrev / Current and their frames), optionally intpl-blending the two frames' vertices when g_bSpyroSubFrameTimer/7d/7e flags are set, runs the GTE transform/lighting pass with shared camera matrix (g_anWorldToCameraRotMtx..e0) and color refs (g_abSpyroPersistentEuler/68/6c), and emits POLY_GT4 / POLY_G4 / sprite primitives into the OT depth bins. Handles a Gouraud color interpolation table at g_anActorDepthCuedVtxColor when distance/depth fog applies. Largest single rasterizer in the binary; investigate further before depending on field interpretations. */
void RasterizeSpyroModel(void);

/* 0x800258f0: World chunk renderer. Loads the camera GTE rotation matrix from g_anCameraViewMtx..df4, then iterates a chunk pointer table: if zone >= 0 it walks that visibility zone's chunk list at g_pVisZoneChunkLists + zone*4 (terminated by byte 0xff); if zone < 0 it walks the full visible-chunk list at g_pWorldChunkArray (length g_nWorldChunkCount). For each chunk, projects its anchor through gte_rtir_b, performs frustum/depth tests, and on visibility emits primitives into the OT depth bins via the scratch buffer at g_abVisZoneGates. Also called by Cutscene_Draw. */
void RenderWorldChunks(int zone);

/* 0x8002a6fc: Per-frame world chunk-animation driver — advances all 6 world chunk-anim tables by step ticks. Called once per game frame from GamestateUpdate. Each table has the layout: count at g_nWorldAnimMeshKeyframeCount/8/70/8/80/8 + ptr-array at g_pWorldAnimMeshKeyframeList/c/74/c/84/c (last pair = g_nWorldAnimVertexMorphCount/a4). Per-entry header bytes: [+1]=state-flags (CHUNK_ANIM_HALTED 0x2 = skip, CHUNK_ANIM_BRANCH 0x1 = follow next_b; a step entry's low two bits are copied in on arrival), [+2]=current step index, [+3]=delay counter, [+4]=target index. Each tick: skip if halted, else delay -= step → if expired advance state via the RLE/state table at +8 (4-byte step entries) or +0xc (8-byte step entries) following the (bit&1?next_b:next_a) successor links; arm new delay from step byte and write its payload to the world target. The 6 sub-tables drive: (1) full-mesh keyframe copy (0xa8-byte vertex blob at g_pWorldMeshVertexData + 0x10-byte header at g_pWorldMeshHeaderArray); (2) UV scroll/cycle that writes 6/12/8/8/8 byte UVs at fixed offsets in iVar3/iVar7 producing a rotating-byte pattern; (3..6) single-byte writes at offsets +0x18..+0x1b of section0-indexed targets (color cycle); (7) packed-21-bit-per-axis vertex morph at g_pWorldAnimVertexMorphList that decodes the source triplet then writes the dest triangle's packed-XY anchors (with optional GTE matrix interpolation when secondary keyframe selected by step byte). Skips advance if not yet due (just decrements delay counter). */
void TickWorldChunkAnimations(int step);

/* 0x8002b4ac: Sibling of TickWorldChunkAnimations that snaps every world chunk-anim table to its current keyframe state without advancing time (no delay decrement, no RLE walk). Same 6 tables: copies the current-keyframe full-mesh blob (0xa8 + 0x10), applies the current UV rotation pattern, writes the current step-index byte to each color-cycle target byte (+0x18..+0x1b), and rebuilds the packed-XY triangle anchors at g_pWorldCollisionHeader+0x10 from the source triplet. Used by the level-loader (BuildLoadedLevelRuntime) to seed all world animations to their initial keyframe before gameplay begins. */
void ResetWorldChunkAnimations(void);

/* 0x8002b9cc: Frame OT/depth setup. Memcopies an empty OT into g_pOtDepthBinHead0 (size 0x1c00), then picks the draw-distance constant g_nFarPlaneDrawDistance by context: In-level (g_nCameraVisZone < g_nVisZoneCount): 0x28000 (far draw distance, the camera's zone list). Story-intro splash / scripted cutscene (GS_TITLE or GS_CUTSCENE): 0x1c000 (close). Otherwise: 0x14000 (default UI / shorter range). Then calls RenderWorldChunks to publish the chosen OT range. */
void SetupFrameOT(void);

/* 0x8002bb20: Returns the "X%" completion percentage shown in the inventory header (Gamestate 3). Formula: (g_nTotalTreasureCollected*50 + g_nTotalDragonsRescued*6000 + g_nTotalEggsRecovered*10000) / 12000 — i.e. 12000 gems = 50%, 80 dragons = 40%, 12 eggs = 10%, Spyro 1's exact 100% split. When treasure exceeds 12000 (Gnasty's Loot's extra 2000), switches to 100 + (treasure-12000)/100, giving the famous 120% cap. */
int ComputeInventoryProgressPercent(void);

/* 0x8002bbe0: Per-frame CD-DA / XA music stream state machine + volume fade ramp. NOT memcard despite earlier triage. Ticked every game frame from GamestateUpdate / PauseMenu_Update / StoryIntro_Update / Cutscene_Update / TickDemoPlayback, and additionally from inside CdReadSyncSectors's wait loop so music keeps advancing during long sync CD reads. (1) Polls CdSync(1, &g_abCdSyncResult); on completion of the in-flight cmd at g_nLastCdMusicCommand (mid-range 8..9 cmds need status-bit 0x200, 0x1b=ReadS uses a different mask), clears the cmd code and stamps g_dwMusicStreamStatus status. If a pending music cmd is queued at g_nPendingMusicCommand, dispatches HandleMusicCommand(track=g_nCurrentMusicTrack, cmd=g_nPendingMusicCommand) and clears the pending slot. (2) If music-stream-active (g_dwMusicStreamStatus bit 0x10): on CdSync==2 idle, if read head g_dwCdMusicReadHead has passed the current track end (g_anMusicTrackEndLbaTable[track*8]), maybe advance to a random track from the per-world triple at &g_nLevelMusicTrack[g_nLevelIndex*0xc/4] (track guard via g_nCdMusicStreamTimeout cooldown vs g_nVblankTickCount timer) then CdControlBlocking(0xd=setfilter, filter=track&7) + CdControl(0x1b=ReadS, LBA), else (still inside track) issues CdControlForce(0x11=getlocL) and copies the absolute time at &0x800776c1 back into g_dwCdMusicReadHead. On CdSync==5 hold, re-issues 0x1b ReadS at the track-start LBA. (3) Volume fade ramp: animates current vol g_nCdDaVolumeCurrent toward target g_nMusicVolumeFadeTarget by g_nMusicVolumeFadeStep step/frame; on reaching target, issues a finalizing CdControl (e.g. cmd 8/9 for unmute/mute via g_nLastCdMusicCommand path) and resets the request. Final volume byte stamped into g_abSpuCommonAttr=0xc0 buffer and pushed via SetSpuCommonAttr. */
void TickCdMusicStream(void);

/* 0x8002bfe0: Scripted-cutscene per-frame driver — interpolates camera transform + per-actor poses from the scripted cutscene path table at g_pPathTableHead. Reads g_pPathTableHead[0] = current sub-frame index, [3] = actor count, [4] = camera keyframe array base (24-byte entries: pos[12]+euler[12]). Writes camera pos to g_anCameraPos/dfc/e00 and Euler to g_nCameraEulerRoll/Pitch/Yaw. Per-actor (i=0..count-1): looks up actor's mob-type byte at *(*(mob_table[id]+0x38)+0xc) to choose a per-mob keyframe-rate divisor — 0x10 → /8 (8fps phase, low 3 bits ×8), 0x15 → /6 (custom), 0x20 → /4, default → /2 (60fps). Stamps actor's per-frame anim-state (4 bytes at record+0x3c..+0x3f for current/next keyframe indices, +0x40 = inter-frame phase byte) and linearly-interpolates XYZ from packed 10-bit-per-component vertex pairs at *(g_pPathTableHead+0x14+id*4) into actor record+0xc/+0x10/+0x14. Sole caller Cutscene_Update. */
void AdvanceCutsceneFrame(int timer);

/* 0x8002c420: Enters GS_PAUSE_MENU: g_nGamestate=GS_PAUSE_MENU, zeros pause-menu cursor/substate/idle frames, plays the menu-open sfx (sample id from g_pLevelSampleBankHeader+0x2c). param nonzero = entered from gameplay/sub-menu (StopAllSoundExceptMask(0) first, resets transition frames); param 0 = re-entry path that forces all 5 HUD counters visible with roll phase 0xc. Flight levels skip the HUD work. */
void EnterPauseMenu(int fromGameplay);

/* 0x8002c534: Exits pause menu back to gameplay: g_nGamestate=GS_GAMEPLAY, restores pause-snapshot framebuffer from g_pRenderScratchPrimTop-0x1c200 via LoadImage, repaints HUD palette indices to {3,…,0xd}, releases memcard slot. */
void ExitPauseMenuToGame(int resumeMusic);

/* 0x8002c618: Begins the pause→world-map curtain animation: g_nGamestate=10 (GS_MENU_TRANSITION), zeros pause idle frames, kicks ChangeSpyroState(NULL,…) to freeze the player. */
void BeginPauseToMenuTransition(void);

/* 0x8002c664: Returns to the current world hub from a sub-level: g_nGamestate=GS_LEVEL_LOAD (logo/splash), g_nGamePaused=1, snaps g_nCurrentLevelId down to world id (id/10*10). Called from SpyroStateDelay_Update at homecoming-portal exit. */
void BeginWorldHubReturn(void);

/* 0x8002c714: Enters GS_INVENTORY (g_nGamestate=GS_INVENTORY); seeds g_nSubMenuCursor to g_nCurrentLevelId/6 so the cursor lands on the active world row; zeros scroll state and clears the pad-history ring. */
void EnterInventoryMenu(int fromGameplay);

/* 0x8002c7bc: Exits the sub-menu back to title (g_nGamestate=GS_GAMEPLAY); restores the title snapshot framebuffer from g_pRenderScratchPrimTop-0x1c200, zeros all five HUD palette indices, releases memcard slot 8. */
void ExitSubMenuToTitle(void);

/* 0x8002c85c: Player death dispatch: if g_nExtraLives > 0 decrement and go to g_nGamestate=4 (GS_RESPAWN); else g_nGamestate=5 (GS_GAME_OVER). Resets g_nRespawnOrGameOverMode/Frame to 0 so the frame counter restarts cleanly. */
void TriggerRespawnOrGameOver(void);

/* 0x8002c8a4: Sets g_nGamestate=GS_GAMEPLAY (gameplay) and restores HUD palette indices to defaults; ends the respawn (state 4) and game-over restart (state 5) paths of RespawnOrGameOver_Update — its only two callers. */
void EndRespawnToGameplay(void);

/* 0x8002c91c: Empty body (single `jr ra`). Placeholder for a removed substate handler in OverlayScreen_Update — likely a stub left over from a cut feature (e.g. an animated logo/title sub-state). Kept as a labeled no-op so the call-site dispatch table stays at a stable offset. */
void Gamestate06SubstateStub_Noop(void);

/* 0x8002c924: Begins the dragon-rescue statue cutscene overlay (g_nGamestate=GS_DRAGON_RESCUE = GS_DRAGON_RESCUE). Seeds the cutscene substate/timer globals, increments BOTH dragon counters in lockstep (g_anLevelDragonsRescued[g_nLevelIndex] per-level + g_nTotalDragonsRescued game-wide total, with the HUD cache primed from the latter), blocks gameplay (g_nCinematicActive=1, g_nGamePaused=1), flags the source actor's render record at +0x3c, anchors the aura star above the statue, and fires the rescue chime sfx. Special cases: Artisans home (level 10) upgrades pickup type 1->2 once any sibling-level g_abLevelExited entry is nonzero; Gnasty's Loot (level 0x3c) rewrites the actor params for the key-locked treasure variant. */
void BeginDragonRescue(Actor *actor);

/* 0x8002cb6c: Returns from the dragon rescue to gameplay: GS_GAMEPLAY, gameplay unblocked, the rescued dragon's linked actor reset (anim 0, mode 1), ResetSpyroEntity(1), a 0xC-frame pad snapshot, the camera anchor back on Spyro with the standing camera (CAM_MODE_STAND) on the dynamic target params, the superflame timer restored and the HUD counters reset (InitHudCounters(0)). */
void EndDragonRescueToWorld(void);

/* 0x8002d02c: Ends the save-menu (GS_SAVE_MENU) back to gameplay: g_nGamestate=GS_GAMEPLAY, resets Spyro (ResetSpyroEntity) + camera mode 0, snapshots the live camera pose INTO g_anCameraDynamicTargetParams (CopyWords from &g_nCameraYaw, 0x18 BYTES = 6 ints), biases slot[0] yaw by g_nCameraTargetYawBiasFromMode, and points g_pCameraTargetParams at it so the world-return camera eases from the menu pose instead of a canned table. Re-inits HUD counters, restores music track. Mirrors EndDragonRescueToWorld. */
void EndSaveMenuToWorld(void);

/* 0x8002d170: Begins the "IN THE WORLD OF DRAGONS…" story intro: g_nGamestate=13 (GS_TITLE, story-intro mode). FillWord zeros 0x5c bytes starting at g_nTitleMode, resets sfx/music volume to 10, primes the title-CD anchor at g_pStoryIntroStreamCursor to the CD buffer end-2000, and kicks the libpress audio start at srand(0x159). */
void BeginStoryIntro(void);

/* 0x8002d228: Begins the credits sequence: g_nGamestate=15 (GS_CREDITS), g_nCreditsMode=-1. Clears the screen to black, calls ResetSpyroEntity(1), loads the credits image via CdReadSyncSectors. reloadMeshes nonzero (post-game variant) also runs LoadActorMeshTables (audio reset) and marks g_nCreditsPageIndex=10 (post-game flag). */
void BeginCreditsSequence(int reloadMeshes);

/* 0x8002d338: Enters the scripted in-engine cutscene (g_nGamestate=GS_CUTSCENE = GS_CUTSCENE). The cutscene id is g_nCutsceneId (the bundle loaded by TickCutsceneBundleLoadStream): 0 = title-screen backdrop (boot, quit to title, demo end), 1 = opening story (skippable, then a new game at level 0xA), 2/3 = ending (credits; see DispatchSpecialCutscene). Builds a 0x10-byte intro packet at &g_CutsceneSoundDef keyed off g_nCutsceneId (cutscene id), with sound bank id from &g_nCutsceneSamplePitch[id], and sets sfx/music vols to max (0x3fff). */
void BeginCutscene(void);

/* 0x8002d440: Dispatches a special-cutscene request based on g_nCutsceneId: 1 → clears screen + g_nGamestate=GS_TITLE (story intro with substate 3 / message 1, calls InitNewGameState to reload the new-game state, jumps to world 10); 2 → BeginCreditsSequence(0) (mid-game credits); 3 → BeginCreditsSequence(1) + sets the post-game marker g_nCreditsPageIndex=10. */
void DispatchSpecialCutscene(void);

/* 0x8002d554: Zeros the 16-slot pad-history ring at g_anPadHistoryRing and resets the write index g_nPadHistoryIndex to 0. Called by cheat-code reset (after a successful match) and by EnterInventoryMenu so cheat sequences don't carry across the menu open. */
void ClearPadHistoryRing(void);

/* 0x8002d580: Level-select (warp) mode input, active while g_nLevelSelectModeActive: face/shoulder buttons pick the sub-level digit (0x20->0, 0x40->1, 0x80->2, 0x10->3, 0x2000->4, 0x4000->5, 0x8000->6); UP (0x1000) auto-advances g_nCurrentLevelId to the next valid id (wraps sub>5 to next world, world>6 back to 10) and arms g_nLevelSelectWorldIndex. A sub-press while a world is armed commits: g_nCurrentLevelId = world*10+sub, resets Spyro (RestartSpyroAnimWithState 0xf), g_nGamestate=GS_LEVEL_LOAD + g_nCdStreamState=1 (level load), camera mode 0x12, clears g_nLevelSelectModeActive, records g_nLevelSelectSubIndex. */
void HandleLevelSelectInput(void);

/* 0x8002d810: Cheat-code dispatch (slot index from CheckCheatCodeMatch). Slot 2 = skip-credits: stashes g_nActiveLevelId in g_nCreditsReturnLevelId then BeginCreditsSequence(0). Slot 3 = unlock: fills g_abLevelVisitedFlag[0..31] with 1 (32 levels, not the egg-less tail) + g_abWorldBalloonistState[0..5] with 2. Slot 4 = g_nExtraLives=99. Slots 0/1/5-7 have no in-EXE effect (their sequences exist in g_anCheatCodeSequences — likely consumed by overlay code, possibly the g_nLevelSelectModeActive raiser). Slots 3/4 play the confirmation jingle (sample id at g_pLevelSampleBankHeader+0). */
void ApplyCheatCodeEffect(int code);

/* 0x8002d8ec: Cheat-code matcher: appends g_dwPadPressed to the 16-slot g_anPadHistoryRing (index g_nPadHistoryIndex); for each of the 8 sequences in g_anCheatCodeSequences (stride 0x40 = 16 ints, 0-terminated) compares the last len presses of the ring; on match calls ApplyCheatCodeEffect(slot) + ClearPadHistoryRing. Only runs while g_nCdStreamState < 0 (no stream in flight). Called from SubMenu_Update (inventory screen). */
void CheckCheatCodeMatch(void);

/* 0x8002da74: Update half of the level-transition gem tally (sole caller LevelLoad_Update; was misread as a logo-splash fire ring). At phase 0 computes g_nGemTallyHoldEndPhase and clears the alive flags of all 64 records at g_pGemTallyParticleRecords (reused g_apSecondaryEntityList storage). Advances g_nLevelTransitionPhase by g_nFrameStep; from phase 0x80 spawns one gem-icon particle per tally unit (i-th at phase 0x80+2i, i < g_nGemTallyIconCount, max 32) with randomized arc params, then flies each through three sine arcs (age 0..0x30 rise, 0x30..0x60 hop, 0x60..0x93 fall into the total counter) and retires it — pickup sfx every 8 phase steps on spawn, chime every 3rd particle on landing. Past phase 0x1a0 clears g_nLevelTransitionTallyActive. DrawLevelTransitionOverlay renders one gem sprite per alive record. */
void AnimateGemTallyParticles(void);

/* 0x8002df9c: g_nGamestate==1 (GS_LEVEL_LOAD) handler: calls TickSpyroFrameGlideHold, UpdateCameraFrame, AnimateGemTallyParticles; conditionally calls TickLevelTransitionStream when g_nCdStreamState<0xb or g_nLevelTransitionTallyActive==0. */
void LevelLoad_Update(void);

/* 0x8002e000: Gamestate 9 handler (set by TickLevelTransitionStream after a level transition): runs a normal gameplay tick (TickSpyroGameplayFrame + UpdateCameraFrame) while the scripted arrival camera settles. Normalizes g_nCameraEulerPitch to signed 12-bit; returns to gamestate 0 when pitch < -0x200 OR g_pCameraTargetParams has latched g_anCameraMode12Params (the mode-0x12 arrival block). */
void CameraSettle_Update(void);

/* 0x8002e084: GS_MENU_TRANSITION (10) handler. Counter g_nMenuTickFrames (reused) increments. At frame 16 (when g_nMenuDrawFrames==0) calls ChangeSpyroState(SPYRO_ST_GLIDE). At frame 32 resets counter, increments g_nMenuDrawFrames; when it reaches 2 calls BeginWorldHubReturn. */
void SpyroStateDelay_Update(void);

/* 0x8002e12c: g_nGamestate==GS_PAUSE_MENU handler. Pause menu input loop: reads g_dwPadPressed (bits 0x10/0x40/0x1000/0x2000/0x4000/0x8000), moves g_nPauseMenuCursor, plays SFX from g_pLevelSampleBankHeader+0x2d..0x2e on every move/select. Sub-mode in g_nPauseMenuSubstate (0=top, 1=options, 2=quit). Cases adjust SFX/music/vibration volumes and quit-to-title. */
void PauseMenu_Update(void);

/* 0x8002eb2c: Gamestate 3 (inventory sub-menu) update. Ticks HUD bob/cycle clocks + RotateLightVectorXZ; after 4 transition frames: if g_nLevelSelectModeActive routes everything to HandleLevelSelectInput; else runs CheckCheatCodeMatch, then horizontal world scrolling — L1/R1-style presses (0x8000/0x2000) start a +/-0x40-per-frame slide of g_nSubMenuScrollOffset toward +/-0x1c0 where g_nSubMenuCursor steps and the offset flips sign (gated on the neighbor world's home-level g_abLevelVisitedFlag via the +/-6 virtual base); 0x810 buttons re-enter the pause menu (EnterPauseMenu(0)), 0x140 exits via ExitSubMenuToTitle. */
void SubMenu_Update(void);

/* 0x8002edf0: Gamestate 4+5 handler (ex-LevelIntro_Update misnomer), mirror of its setter TriggerRespawnOrGameOver. State 4 (lives left): wait 0x10 frames, EndRespawnToGameplay + LoadAndStartLevelFromCd reload. State 5 (game over): CD-loads the game-over scene, resets g_nExtraLives=4 / sparx, latches g_nGameOverLevelIndex, FillWord-clears the 0x68-byte level-persistence block, then flies Spyro in a spiral (frames 0xb4..0x174) over the GAMEOVER letters until Start (pad 0x800) restarts via TickLevelTransitionStream. */
void RespawnOrGameOver_Update(void);

/* 0x8002f3c4: Gamestate 6 handler — intentionally empty (calls the no-op substate stub). NO in-EXE writer ever sets g_nGamestate=GS_OVERLAY_SCREEN (full setter map audited sweep 45: 1=HandleLevelSelectInput/BeginWorldHubReturn/portal, 2=EnterPauseMenu, 3=EnterInventoryMenu, 4/5=TriggerRespawnOrGameOver, 7=PauseMenu_Update overlay handoff, 8=BeginDragonRescue, 9=TickLevelTransitionStream, 0xA=BeginPauseToMenuTransition, 0xD=BeginStoryIntro/DispatchSpecialCutscene, 0xE=TickDemoPlayback, 0xF=BeginCreditsSequence) — state 6 is entered only by overlay code poking g_nGamestate by absolute address. Its Draw path (Gamestate02_03_06_Draw) renders just the grayscale frozen-scene backdrop + whatever sprites the overlay enqueued: an overlay-rendered menu/dialog state (balloonist dialogue is the prime candidate; confirm when overlay disassembly lands). */
void OverlayScreen_Update(void);

/* 0x8002f3e4: g_nGamestate==8 (GS_DRAGON_RESCUE) handler. 8-state submachine via g_nDragonRescueSubstate (0..7) and g_nDragonRescueTimer drives the gem-collect / dragon-rescue overlay: camera orbits via ArcTan2 + LookupSine/Cosine, spawns icons g_pDragonRescueStatueActor/bc, plays sfx bank g_pLevelSampleBankHeader+0x31..0x35. Substate 7 ends via EndDragonRescueToWorld back to GS_GAMEPLAY. */
void DragonRescue_Update(void);

/* 0x800314b4: g_nGamestate==0xB (GS_SAVE_MENU) handler. */
void SaveMenu_Update(void);

/* 0x800324d8: GS_ACTOR_CUTSCENE (0xC) handler. Drives substate 4, the camera fly-in to the level entry point (g_anLevelEntryPoints); every other substate runs g_pfnActorCutsceneSubstateUpdate. */
void ActorCutscene_Update(void);

/* 0x80032b08: g_nGamestate==GS_TITLE primary handler — the story-intro flow ("IN THE WORLD OF DRAGONS…"). Reached when g_nTitleMode==TITLE_MODE_STORY_INTRO; other modes dispatch into Gamestate0D_Alt (overlay slot at g_abAssetDirectoryBuffer+0x174). Drives a 3-state submachine via g_nStoryIntroSubstate (0=enter/CD-load init, 1=stream tier-N CD chunks until ready, 2=camera fly-by + per-glyph text emit, ends by either BeginCutscene or fading to level-load). g_nTitleExitPath selects the variant (0='IN THE WORLD OF DRAGONS...', then the opening-story cutscene; 1='THE ADVENTURE BEGINS/CONTINUES...', then the level; 2='ENTERING DEMO MODE...', loads g_anDemoLevelIds[g_nDemoIndex] and arms g_nDemoMode = 1). */
void StoryIntro_Update(void);

/* 0x800331ac: g_nGamestate==0xE (GS_CUTSCENE) handler. Paired with Cutscene_Draw (the cutscene render). On entry (timer==0, cutscene id > 1) it issues a synchronous CD-load loop and re-seeds via BeginCutscene; per tick it advances *g_pPathTableHead (timer) toward threshold g_pPathTableHead[2]*2, fades g_nScreenFadeLevel at both ends, then calls DispatchSpecialCutscene to hand off to BeginStoryIntro / BeginCreditsSequence when finished. */
void Cutscene_Update(void);

/* 0x800333dc: g_nGamestate==0xF (GS_CREDITS / returning-home) primary handler. Reached when g_nCreditsMode >= 99. mode 99 = init: picks return-to-hub level (60 normal / 10 post-game when g_nTotalTreasureCollected==14000), zeros g_nReturningHomePhase, transitions mode to 100. mode 100 = tick: bumps phase, drives TickLevelTransitionStream (level transition state machine). Modes <99 (e.g. -1 from BeginCreditsSequence) dispatch into Gamestate0F_Alt — an overlay slot at g_abAssetDirectoryBuffer+0x18 (post-.bss RAM) that the credits CD-stream populates at runtime. */
void CreditsSequence_Update(void);

/* 0x800334d4: Attract-demo playback watcher. Called from the GamestateUpdate gameplay path while g_nDemoMode != 0 (also samples the pad via SampleDemoPadFrame). Starts the exit fade once the demo has run g_anDemoLengthFrames[g_nDemoIndex] - 8 frames or the real pad shows a press; at fade frame 16 it stops sound, clears VRAM, ends the demo (g_nDemoMode = g_nDemoActive = 0), reloads cutscene bundle 0 (the title backdrop), enters GS_CUTSCENE + BeginStoryIntro, and advances g_nDemoIndex (&3). A demo that ran its full length restarts the title flyover at path frame 0x2D0 with the title sample; an interrupted one at 0x490. Returns 1 when the demo ended this frame (caller skips the rest of the frame). */
int TickDemoPlayback(void);

/* 0x8003385c: Per-frame main-loop dispatcher (called from main @ main). 16-way switch on g_nGamestate: 0 = active gameplay (heavy path: input, physics, camera, early/late hooks g_pfnLevelUpdateActors/LateHook, pause/inventory entry); 1 = LevelLoad_Update; 2 = PauseMenu_Update; 3 = SubMenu_Update; 4,5 = RespawnOrGameOver_Update (4 = death respawn with lives left, 5 = game over); 6 = OverlayScreen_Update; 7 = (*g_pfnGamestate7Handler)() overlay hook; 8 = DragonRescue_Update (dragon rescue); 9 = CameraSettle_Update; 0xA = SpyroStateDelay_Update; 0xB..0xD per-state updates (0xD mode-switched on g_nTitleMode); 0xE = Cutscene_Update; 0xF = CreditsSequence_Update/Alt switched on g_nCreditsMode (>=99 = returning-home/credits). The attract-demo watcher TickDemoPlayback flips to state 0xE when a demo ends. */
void GamestateUpdate(void);

/* 0x80033c50: Builds the 3x3 camera view matrix from g_nCameraEulerPitch/Yaw/Roll (X * Y * Z order). Writes the full matrix to g_anCameraViewMtx and a Y-row-scaled-by-0x140>>9 copy to g_anWorldToCameraRotMtx (the projection-ready variant). Stack matrix is reused as both accumulator and scratch. */
void BuildCameraViewMatrix(void);

/* 0x80033e40: Line-of-sight segment test. Marches from from toward to in 0x400-length steps (segment length / 0x400 iterations) and calls CastRayWorldAndActors (world collision query) at each step. Returns 1 if every step is clear, 0 on the first hit. Shared by UpdateGameplayCamera for camera occlusion tests; M07 will likely reuse for projectile and entity LOS. */
int CheckLineOfSightSegment(int *from, int *to);

/* 0x80033f08: Derives the camera pitch / yaw from the anchor -> `target` delta; when the inverted heading is closer (or the mode / target asks for it) flips the framing half a turn and returns 1, else commits the plain yaw and returns 0. */
int ComputeCameraToTargetAngle(int *target);

/* 0x80034198: Loads the current camera-mode's 6-int parameter block from g_pCameraTargetParams into the g_nCameraTarget* set (Yaw, Pitch, Distance, Roll, PitchBias, YawBias). The yaw is biased by -g_nCameraTargetYawBiasFromMode & 0xfff so the params can be stored in world-space yaw. */
void LoadCameraTargetAnglesFromMode(void);

/* 0x80034204: Polar-to-Cartesian for the camera orbit. Writes (x = D*Cos(P)*Cos(Y), y = -D*Cos(P)*Sin(Y), z = D*Sin(P)) into *out using g_nCameraSpringYaw/Pitch/Distance. The result is the offset from g_pCameraAnchorPos to the eye position. */
void ComputeCameraOrbitOffset(int *out);

/* 0x800342f8: Final blend of the spring biases into the Euler angles consumed by BuildCameraViewMatrix. EulerPitch = Pitch + SpringPitchBias; EulerRoll = SpringRoll; EulerYaw = (0x800 - SpringYawBias) - Yaw. All wrapped & 0xfff. */
void UpdateCameraEulerAngles(void);

/* 0x80034358: Hard-reset of the camera spring state to the current target. Clears tracking accumulators (g_anCameraSpringDeltaState..e98 and g_nCameraShakeDuration, g_nCameraShakeMagnitude), copies the g_nCameraTarget* set into g_nCameraSpring*, derives a fresh eye position via ComputeCameraOrbitOffset + g_pCameraAnchorPos, then primes the smoothed-position copy and runs one ComputeCameraToTargetAngle + UpdateCameraEulerAngles pass. */
void ResetCameraStateToTarget(void);

/* 0x80034480: Per-frame gameplay camera update. Marches the smoothed camera position toward the desired eye in 0x100-sized substeps; at each substep runs CollideSphereWithWorldAndActors and slides off the surface using the contact at g_anCollisionResolvedPos. On LOS-clear (g_nCameraLosClear=1) decrements g_nCameraCollisionRetries; on occlusion (=0): after 0x1e stuck frames first re-seats via the 5 mode-param blocks at &g_anCameraStuckReseatParams (g_pCameraTargetParams + ResetCameraStateToTarget), then probes g_anCameraEscapeOffsets (5 yaw/pitch/dist offset records at 1x, 2x, 4x scale) for a collision-free seat with two-way line of sight. Calls ComputeCameraToTargetAngle each frame to refresh g_nCameraYaw/Pitch/Distance, then runs two CheckLineOfSightSegment probes between the eye and the look-at point g_anSpyroWorldPos. */
void UpdateGameplayCamera(void);

/* 0x80034c84: Teleports the smoothed camera position to the current eye (g_anCameraEyeTarget -> g_anCameraPos), zeros the spring tracking state, raises g_nCameraSnapped + g_nCameraLosClear, and rebases the camera-to-target angles via ComputeCameraToTargetAngle. Called when a discontinuous camera cut is needed. */
void SnapCameraToTarget(void);

/* 0x80034ce8: Per-frame 6-axis camera spring step. column = tuning-set COLUMN (0..5) into g_anCameraSpringDriveGains (K0) / g_anCameraSpringDampingGains (K1) / g_anCameraSpringSnapThresholds: callers pass min(4, (g_nCameraStuckFrames+1)>>1) (collision-stuck stiffness escalation), 5 for scripted modes (mode 9 script-stick; mode 0xa with g_dwSpyroRequestMask & 0x1000), 0 from UpdateLevelTransitionCamera and the mode-6 settle loop. For each axis (Yaw, Pitch, Distance, Roll, PitchBias, YawBias): g_anCameraSpringDeltaState[axis] += (K0*delta - K1*accum) >> 8, snaps to 0/±0x100 below threshold (g_nCameraSnapped), then adds (accum >> 8) to the matching g_nCameraSpring* angle. Yaw uses g_nCameraManualYawInput as drive override (R1/L1 rotate); mode 6 (latched gem-grab) zeros all drives. Clamps: ±0x800 in headbash state (0xf/0xb) and passive-camera reengage; ±0x2000 with option bit 0x40 in modes 9/3. */
void AdvanceCameraSpringStep(int column);

/* 0x800357a4: Per-frame camera-mode arbiter. Holds/clears the sentinel modes against g_dwSpyroRequestMask bits (0x200 mode 0xa transition, 0x400 mode 0xb portal path, 0x8000 mode 7 scripted target, 0x10000 mode 0xc scripted follow) and otherwise falls back to g_abSpyroStateCameraMode[g_nSpyroState]. Mode 9 (free-look, option 0x10 passive): exits to mode 0x80000010 with g_nCameraPassiveModeHoldTimer = 0x2d when Triangle (PAD_TRIANGLE, held bit 0x10 in g_dwPadHeld) releases in SPYRO_ST_IDLE / SPYRO_ST_TEETER. Modes 0x10/0x11 persist while g_nCameraPassiveModeHoldTimer > 0 and the state-table mode is 0/4. Passive-idle recenter: when mode 0 with passive camera and Spyro near the screen anchor (projected |x−0x100| ≤ 0x40, |y−0x78| ≤ 0x28, depth ≤ 0x1400 via ProjectWorldPointGTEUnscaled), re-enters mode 0x10; a generic mode change with passive idle instead enters mode 0x80000011 with timer 8 + g_nCameraSpringReengageCountdown 0x5a. On mode-0xb entry seeds the path index (0 forward / count−1 reverse) in g_pPortalCamPathData per g_nPortalCamPathReverseFlag. On commit re-snaps the spring state to the recomputed g_nCameraYaw/Pitch/Distance (modes 2/0xe too); entering mode 9 zeros g_anCameraScriptStickIntegrator and clears g_nCameraCollisionRetries if LOS is clear. */
void SelectCameraMode(void);

/* 0x80035f58: Reads R1/L1 camera-rotate input bits at g_dwPadHeld (bits 0/1) and writes ±0x400 to g_nCameraManualYawInput — the yaw-drive override consumed by AdvanceCameraSpringStep. Suppressed when (g_dwSpyroRequestMask & 0x1000) is set or when g_nCameraStuckFrames != 0. Called by UpdateCameraSpringForMode for modes that allow manual camera rotation; the rotation-blocked modes (0x80000009 free-look, 0x80000012 ledge, 0x8000000b gem-grab, 0x8000000e, mode 3) zero g_nCameraManualYawInput directly instead. */
void UpdateCameraManualYawInput(void);

/* 0x80035fb4: Per-frame camera spring driver. Dispatches off g_nCameraCurrentMode to pick the target-params block (g_anCameraParamDefault / Mode2Front/Reverse / Mode3 / Mode4Front/Reverse / Mode5LeftBias/RightBias / Mode9ScriptStick / ModeC_ScriptedFollow / ScriptedTarget) and the anchor (g_anSpyroWorldPos for most modes; g_anCameraScriptedTargetPos from g_pScriptedCameraActor for mode 0x80000007; latched copy g_anCameraLatchedAnchorPos for mode 6). Computes the spring tuning column iVar9 = min(4, (g_nCameraStuckFrames+1)>>1), overridden to 5 for modes 9 / 0xa-with-request-0x1000, then runs AdvanceCameraSpringStep(column) x g_nFrameStep, ComputeCameraOrbitOffset, UpdateGameplayCamera + UpdateCameraEulerAngles. MODE 6 (latched gem-grab): springs only advance while sum(|g_anCameraSpringDeltaState[0..5]|) > 0x20 — the settle threshold (the old 'slti 0x21' question) — then SnapCameraToTarget; once settled the camera freezes. Mode 9 integrates the right stick / D-pad into g_anCameraScriptStickIntegrator (via g_pPadSubstepState or g_dwPadHeld) onto g_nCameraTargetYaw/Pitch and publishes counter-request g_nSpyroSwingEulerTargetZ/Y. Passive-camera (option 0x10 / look-around) idle path: while g_nPadAllInputIdleFlag with LOS clear in mode 0, counts down g_nCameraSpringReengageCountdown (0x5a) before re-engaging the auto spring; modes 0x10/0x11 decrement g_nCameraPassiveModeHoldTimer. Look-ahead: target yaw-bias = angle(player) − angle(player + motionvec * g_bCameraLookaheadMotionScale >> 5|6) in modes 1/2/5. Ends by re-running ComputeCameraToTargetAngle to re-sync the spring state with the smoothed eye position. */
void UpdateCameraSpringForMode(void);

/* 0x8003740c: Camera updater for mode 0x8000000b (portal spline path). Walks g_anCameraPos along the overlay-provided path at g_pPortalCamPathData: count byte [0], current index byte [1], waypoint vec3s at +8 + i*0x10. Within 0x200 of the current waypoint the index advances (g_nPortalCamPathReverseFlag == 0) or retreats. Speed: while an onward waypoint exists, dot(camera→player excess beyond 0x400, segment tangent normalized to 0x1000) <<7 >>12 (capped 0x80); at the path ends, distance capped by g_nPortalCamPathMaxStep. Step = ScaleVector3ByRatio(toWaypoint, dist, speed * g_nFrameStep); finishes with ComputeCameraToTargetAngle + UpdateCameraEulerAngles to keep the angles in sync. */
void UpdatePortalPathCamera(void);

/* 0x80037714: Sets the active scripted-camera record (g_pScriptedCameraView), snaps the smoothed eye position g_anCameraPos to the record's stored eye at +0x18, zeros velocity at g_anSpyroVelocity, sets g_nSpyroVelocityZ=-0x2300 (default Z), loads Roll/Pitch/Yaw from record offsets +0x24/+0x28/+0x2c into g_nCameraEulerRoll/Pitch/Yaw, then forces both camera mode slots to 0x8000000e. Called only by UpdateScriptedCameraView when selecting a new vantage. */
void ActivateScriptedCameraView(int *view);

/* 0x800377a8: Camera updater for mode 0x8000000e (scripted vantage triplet). Once the level-load stream has finished (g_nCdStreamState < 0), picks the next mode from &g_abSpyroStateCameraMode unless the current camera state matches the override list (modes 6/0x10/0x20/0x21/0x22/0xf/0x1d). When the active scripted-camera record (g_pScriptedCameraView) is exhausted — either the player has moved further than the record's max distance (field 0xd) OR the player has left the camera-screen window via ProjectWorldPointGTEUnscaled (Y > 0xf0) — picks one of 3 ROM records at &g_anScriptedCameraPresetRecords (stride 0x38), avoiding immediate self-repeat, and calls ActivateScriptedCameraView. Refreshes camera euler angles when the record's type field at +0x30 == 1. */
void UpdateScriptedCameraView(void);

/* 0x80037a20: Camera updater for mode 0x80000012 (level transition: set with GS_LEVEL_LOAD by portal entry, BeginWorldHubReturn and HandleLevelSelectInput; holds on Spyro while the next level streams). Anchors on the player (&g_anSpyroWorldPos) with yaw bias from level yaw g_nSpyroBodyYaw. Picks the target-params block based on whether yaw is above/below the level yaw (g_anCameraParamTransitionYawBelow vs g_anCameraParamTransitionYawAbove) or, when g_nReturnPortalLevelId is set, by submode threshold (g_anCameraParamTransitionStreaming vs g_anCameraParamMode2Reverse). Zeros the yaw torque, runs the spring step (axis 0) per frame-step, recomputes the eye position via ComputeCameraOrbitOffset + AddVector, then SnapCameraToTarget + UpdateCameraEulerAngles + ComputeCameraToTargetAngle. Copies the auto-aim outputs into the spring set so subsequent frames smoothly leave the freeze. */
void UpdateLevelTransitionCamera(void);

/* 0x80037bd4: Top-level per-frame camera updater. Called from gameplay state Updates (CameraSettle/LevelLoad/SpyroStateDelay/DragonRescue + the main GamestateUpdate). Sets g_nCameraForcePassiveFollow=(camera-mode-state==0x1b) and picks the next mode from the per-state byte table at &g_abSpyroStateCameraMode[g_nSpyroState]. Calls SelectCameraMode to commit g_nCameraCurrentMode, then dispatches: 0x8000000e → UpdateScriptedCameraView, 0x80000012 → UpdateLevelTransitionCamera, 0x8000000b → UpdatePortalPathCamera, else → UpdateCameraSpringForMode. Tail handles camera shake (g_nCameraShakeDuration countdown) and the per-level-mode camera distance/LOS check (g_nCdStreamState negative branch). */
void UpdateCameraFrame(void);

/* 0x80038dc0: Turns an actor's byte yaw (Actor.rotZ) toward Spyro (ArcTan2 of g_anSpyroWorldPos - actor position). Camera-mode boost: g_nActorFrameDelta == 3 → step *= 1.5; == 4 → step *= 2. Returns 1 once within threshold deadzone (flag != 0 still applies one ApproachAngle8 step at lock-on); returns 0 while still rotating. Callers: the level actor updates (actors that face Spyro) and SaveMenu_Update. */
#ifndef YAW_HOLD_IN_BAND
#define YAW_HOLD_IN_BAND 0 /* inside the threshold band: stop turning */
#define YAW_STEP_IN_BAND 1 /* inside the band: keep stepping onto the target */
#endif
int TrackEntityYawTowardSpyro(Actor *actor, int step, int threshold, int flag);

/* 0x8003a720: Zero/default initializer for an actor's render-state block (offsets +0x18..+0x57 from record base). Sets two PsyQ POLY_F3 prim-type tags (0x20) at +0x41 and +0x4b, full-bright RGB intensities (0xff) at +0x43/+0x4a/+0x52/+0x53, fade level 0x7f at +0x54, default counters 0x10 at +0x50 + 4 at +0x47 + 1 at +0x3f, and clears byte yaw/pitch/roll at +0x44..+0x46 plus all state words at +0x18/+0x1c/+0x38/+0x4c. Callers: TickCutsceneBundleLoadStream (level loader, M09) + DragonRescue_Update. */
void InitActorRenderDefaults(Actor *actor);

/* 0x8003c6e4: Per-frame kinematic tick for a dragon-rescue burst entity. Reads a velocity/rotation sub-record at *actor: [0/1/2] = vx/vy/vz, [3] = z floor threshold, byte +0x11/12 = rotation rates, byte +0x13 = TTL counter. Per tick: pos += vel (vec3 at +0xc/+0x10/+0x14); vz -= 6 (clamped at -0x80, gravity); byte angles at +0x44/+0x45/+0x46 += rotation rates; TTL counter decremented; every other frame spawns 1 sparkle via (*g_pfnLevelEmitParticles)(1, EMIT_SPARK_VEL_DIM, &pos, &localBuf). On TTL == 0 OR pos.z <= z-floor: spawns the 0x46-particle final burst (cmd 3) and calls DespawnActorRecord to despawn the entity. Caller: DragonRescue_Update. */
void TickStatueBurstShard(Actor *actor);

/* 0x8003cb24: Adds delta to the sub-frame timer g_bSpyroSubFrameTimer. On overflow past 0xf, advances g_bSpyroAnimFrame by 1 within current anim, wrapping back to g_abSpyroAnimDescTable[anim*4] (loop start) when it reaches [anim*4+1] (loop end). Pure incremental step — does not change state. */
void AdvanceSpyroAnimFrame(int delta);

/* 0x8003cbb8: Frame stepper with state-transition commit. Like AdvanceSpyroAnimFrame but when the current anim hits its total frame count (g_abSpyroAnimDescTable[anim*4+2]), commits the pending state change and loads the new state's default anim g_abSpyroStateAnimIndexMap[g_nSpyroState]. Restart style comes from g_abSpyroStateTransitionAnimMatrix[newState + prevState*0x2d]: entry 10 = restart at the anim's loop-start frame (g_abSpyroAnimDescTable[anim*4]), else partial restart at frame 1 with sub-frame timer 4. Returns 1 if the transition committed, 0 otherwise. */
int StepSpyroAnimAndCommitTransition(int step);

/* 0x8003cce4: Applies a pending Spyro state transition. Reads transition-action byte at &g_abSpyroStateTransitionAnimMatrix[g_nSpyroState + g_nSpyroPrevState*0x2d] (case 1..0xb) and dispatches to one of 9 anim-restart strategies. Sets g_nSpyroAnimMode (anim sub-state code), g_bSpyroAnimCurrent/77 (current anim/frame), g_bSpyroSubFrameTimer (timer). Also handles case-4 break-out to a fresh anim when transitioning from SPYRO_ST_FALL with g_nSpyroPrevStateTimer < 0x18. */
void ApplySpyroStateTransition(void);

/* 0x8003d194: Per-frame Spyro animation state-machine tick. Routes on g_nSpyroAnimMode (0..10): case 0 = advance frame (no pending transition) or ApplySpyroStateTransition; cases 1/2/6 = advance sub-frame timer by 2; cases 3/10 = stepped transition — only when g_abSpyroStateTransitionAnimMatrix[g_nSpyroState + g_nSpyroPrevState*0x2d] is 3/4/10, calls StepSpyroAnimAndCommitTransition at the previous anim's play rate (plays the landing SFX when prev anim was 0x1a); case 4 = wait for sub-frame overflow then enter mode 3; cases 5/8 = advance with a specific increment then drop back to mode 0. */
void TickSpyroAnimStateMachine(void);

/* 0x8003d3b8: Reads the current pad (via g_pPadSubstepState) and converts directional input into a movement target. Analog stick (offsets +0x16 +0x17 centered at 0x7f) maps to ArcTan2 → target yaw g_nSpyroMoveTargetYaw + magnitude-scaled speed g_nSpyroSpeedTarget. D-pad (button bits in +4 nibble 0xf000) maps via the 16-entry yaw table at &g_anDpadDirectionYaw (stride 2). Both paths combine with g_nCameraEulerYaw so movement is camera-relative. */
void ComputeSpyroMoveTargetFromPad(int speed);

/* 0x8003d52c: Applies sin/cos integration of body-frame angular velocity (rate) to update world-frame Euler angles. Reads current pitch (g_nSpyroBodyPitch) and yaw (g_nSpyroBodyRoll) via the LUTs, then increments yaw (g_nSpyroBodyRoll), roll (g_nSpyroBodyYaw), and pitch (g_nSpyroBodyPitch) by the cos/sin-projected components. Also updates the byte snapshots g_abSpyroPersistentEuler/65/66 (12-bit angles >> 4). The cos(pitch) denominator divisor models a pitch-coupled yaw scaling. */
void IntegrateSpyroBodyEuler(int rate);

/* 0x8003d6d0: Steers Spyro's body yaw (g_nSpyroBodyYaw) toward the move target yaw (g_nSpyroMoveTargetYaw) using a lean accumulator (g_nSpyroBodyYawStep, range -6..+6). Picks turn rate from the 2D lookup table at &0x8006c5fc + bucket * 0x1a + lean * 2 (bucket selects speed bucket). Resets lean when target is overshot or the desired delta falls inside the table-indexed band. Always finishes by calling IntegrateSpyroBodyEuler with the chosen angular delta and reports the new |delta| via AbsAngleDelta12. */
int TurnSpyroTowardMoveTargetWithLean(int bucket);

/* 0x8003d840: When the analog stick is past the inner deadzone (button bit and not centered at 0x7f7f) but its magnitude is < 0x60, smooths Spyro's body yaw (g_nSpyroBodyYaw) partway toward the move target yaw (g_nSpyroMoveTargetYaw) proportional to stick magnitude. Large delta (> 0x100) sets the snap-flag g_nSpyroSubstate = 1. Always follows with TurnSpyroTowardMoveTargetWithLean(0). */
int ApplyPadInputToSpyroBodyYaw(void);

/* 0x8003d92c: Accelerate/decelerate current speed (g_nSpyroMotionSpeed) toward the target speed (g_nSpyroSpeedTarget) using two separate ramps: +accel per frame when below target, -decel per frame when at-or-above. Clamps to the target on overshoot. The split rates let walking states use a softer brake than throttle. */
void AdvanceSpyroSpeedTowardTarget(int accel, int decel);

/* 0x8003d978: Compose Spyro's linear velocity vector (g_anSpyroVelocity..b54) by rotating (speed,0,0) through the body Euler matrix. Builds the matrix into stack via ApplyEulerRotation from the byte snapshots of pitch/roll/yaw (g_nSpyroBodyPitch/74/78 >> 4), then RotateVectorByMatrix expands the speed (g_nSpyroMotionSpeed) along the body forward axis. */
void BuildSpyroVelocityFromBodyEuler(void);

/* 0x8003da08: Free-fall body attitude damper. Spring-damps pitch (g_nSpyroBodyPitch) and yaw (g_nSpyroBodyRoll) back toward 0 via the angular accumulators g_nSpyroPitchSpringVel / g_nSpyroRollSpringVel with PD coefficients (4/16 - 16/64). No target-velocity tracking — used when Spyro is too high above ground (g_nSpyroGroundSlope ≥ 0x17) for UpdateSpyroFlightAttitudeNearGround. */
void DampenSpyroFreeFallAttitude(void);

/* 0x8003dae4: Per-frame attitude controller for glide/flight when Spyro is close to ground (g_nSpyroGroundSlope < 0x17). Spring-damps body pitch (g_nSpyroBodyPitch) and yaw (g_nSpyroBodyRoll) toward velocity-relative angles derived from the local ground frame and body yaw, using the angular accumulators g_nSpyroPitchSpringVel/cb4. When both byte snapshots g_abSpyroPersistentEuler/65 are tilted past 0xc0+0x20, layers an additional position offset on g_anSpyroWorldPos (Spyro pos) for the ground-hug effect. Falls through to DampenSpyroFreeFallAttitude when above the 0x17 altitude threshold. */
void UpdateSpyroFlightAttitudeNearGround(void);

/* 0x8003de44: Spring-aligns Spyro's body pitch (g_nSpyroBodyPitch) and yaw (g_nSpyroBodyRoll) to the current velocity (g_anSpyroVelocity..b54). Computes target pitch as -ArcTan2(|XY|, Z) and target yaw as ArcTan2(vx,vy)+0x8e, drives g_nSpyroPitchSpringVel/cb4 angular accumulators with PD coefficients (4/16 - 16/64) and integrates the result. Used by free-flight states where the body should "face the way it's moving". */
void AlignSpyroBodyToVelocity(void);

/* 0x8003dfa4: Hard-zero of Spyro's linear motion. Clears the knockback accumulator g_anSpyroMotionVec..b6c, the frame-delta length g_nSpyroFrameMotionLength, the live velocity g_anSpyroVelocity..b54, and the speed scalar g_nSpyroMotionSpeed. Called by jump/glide/dive transitions (DispatchSpyroPadStateChanges/41270/41670) just before they overwrite velocity with their own launch. */
void ResetSpyroLinearMotion(void);

/* 0x8003dfec: Rotates Spyro's body yaw (g_bSpyroPersistentEulerZ byte / g_nSpyroBodyYaw word) by ±step toward the knockback direction ArcTan2(g_anSpyroMotionVec, g_nSpyroMotionY). The 8-bit angle delta must lie outside the ±band dead-band; if it also escapes ±step, the body snaps directly to the target rather than stepping. Used by IntegrateSpyroMotionForSubstep (on-ground update) to recover orientation after impacts. */
void RotateSpyroBodyTowardKnockbackDir(int step, int band);

/* 0x8003e0b4: Decomposes gravity along the slope tangent of the current surface. Computes the component of gravity (g_nSpyroGravityStep) projected onto the ground plane defined by normal g_anSpyroGroundNormal and writes the down-slope acceleration into 0x80078b28 (with g_nSpyroSlopeGravityStep = gravity magnitude). Called by ChangeSpyroState cases 0xb (charge), 0x13, 0x2c to give Spyro a slope-slide push along the ground tangent. */
void ApplyGravityAlongSpyroSlopeTangent(void);

/* 0x8003e1ac: Sets g_anSpyroSlopeGravityVec to gravity-magnitude pulling Spyro along the negated ground normal. Copies g_anSpyroGroundNormal (surface normal) into g_anSpyroSlopeGravityVec, scales length to |g_nSpyroGravityStep| (gravity), then negates. Combines with ApplyGravityAlongSpyroSlopeTangent to fully decompose gravity onto the slope frame. Called widely from ChangeSpyroState (cases 1/2/3/7/0xe/0x15/0x16/0x1a/0x1c/0x1e/0x1f/0x2c) for slope-aware launches. */
void ApplyGravityAlongSpyroSlopeNormal(void);

/* 0x8003e218: Cliff-detection probe: fires a LOS (CastRayWorldAndActors) from a point ahead-and-down of Spyro (body-frame offset 0x1c4, 0, -0x164) toward a point further-down (GTE-rotated 0, 0, -0x1a4) relative to g_anSpyroWorldPos. If the probe hits ground and the slope angle is steep (> 0x16 in 8-bit angle units), latches g_nSpyroWallSlideContributedFlag = 1 (ledge-detected flag) and snapshots the hit normal into g_anSpyroWallSlideNudgeAccum..b18. Used by ground-state to trigger cliff-aware behavior. */
void ProbeSpyroLedgeForward(void);

/* 0x8003e318: Per-frame Spyro grounding probe (skipped when g_dwSpyroRequestMask bit 0x4000 is set). Fires LOS from a body-frame point above Spyro to a point below; on hit, captures the surface normal into g_anSpyroGroundNormal..b04, computes the slope angle into g_nSpyroGroundSlope, stores the world-chunk id into g_nSpyroGroundChunkId, and loads chunk vertices into g_anSpyroGroundChunkVerts+ via UnpackWorldCollisionTri. Slope < 0x21 marks footing (g_nSpyroAirborneFrames = 0 contact frame counter); steeper triggers the fallback inner downward probe (vertical line to z=-0x3c). Updates g_nSpyroCliffEdgeHint if a secondary forward-down LOS fails (cliff-edge hint). */
void ProbeSpyroGroundContact(void);

/* 0x8003e628: When standing on a known world chunk (g_nSpyroGroundChunkId >= 0), averages the per-vertex displacement of the chunk's first 3 vertices vs. their cached values at g_anSpyroGroundChunkVerts+ (loaded by ProbeSpyroGroundContact). Stores the mean delta into g_anSpyroPendingImpulse — Spyro's "moving-platform" inherited velocity, applied by the per-frame physics integrator. Significant motion (length > 0x20) sets g_nCameraSpringSuppressFlag = 1 to wake camera tracking. */
void AverageSpyroPlatformMotion(void);

/* 0x8003e758: Sub-frame footing recovery: fires LOS (CastRayWorldAndActors) from a body-frame point (X+0x80) to a point (Z-0x164, Z-0x80) and, on a hit with positive height delta, subtracts the world-collision delta from the hit position (relative to g_anCollisionResolvedPos GTE reference) and applies the small displacement (per-component cleared if abs < 8) to g_anSpyroWorldPos (Spyro pos). Clears the off-ground counter g_nSpyroAirborneFrames on success, otherwise increments it. Acts as the per-frame "snap-to-floor" step. */
void StepSpyroOntoLocalFloor(void);

/* 0x8003e90c: Cliff-edge / wall-clear nudge: fires 4 LOS probes (CastRayWorldAndActors) around Spyro using delta vectors at &0x8006ccb8/cbf8 stride 0x40, builds a 4-bit hit mask, then looks up a clear-direction index in the 16-entry table at &g_anSpyroWallNudgeAngleByProbeMask. If index ≥ 0, applies the corresponding (X,Z) nudge from &g_anCosineLut/cbf8 (>>4 scaled) to velocity g_anSpyroVelocity/b50. Called by ChangeSpyroState cases 6 (cliff-fall) and 0x10 (break-out) when g_nSpyroGroundSlope < 0x20 — pushes Spyro horizontally clear of geometry. */
void NudgeSpyroFromWallProbes(void);

/* 0x8003ea68: Spyro state-change entry point: per-new-state initialization switch (state = the new SpyroState). Exit-side preamble: leaving certain states stops/plays exit SFX from g_pLevelSampleBankHeader bytes. Per-state setup writes the movement core (g_nSpyroSubstate, g_nSpyroGravityStep/EnableFlag, velocity/carry vectors, g_nSpyroFloorReferenceZ) — notably: WALK/RUN/STOP/JOG compute g_nSpyroMoveTargetMag from g_anSpyroSlopeSpeedTargets interpolated by ground slope; SPYRO_ST_CHARGE scans the actor list for the nearest chargeable target in a 0x200-yaw cone; SPYRO_ST_IDLE and the fidget states (SPYRO_ST_FIDGET_*) seed g_nSpyroIdleAnimTimeout. Tail commits g_nSpyroState/g_nSpyroPrevStateTimer, zeroes g_nSpyroStateTimer, and loads g_nSpyroAnimPlayRate from g_abSpyroAnimDescTable via g_abSpyroStateAnimIndexMap. */
void ChangeSpyroState(int state);

/* 0x8003fdc8: Wrapper: calls ChangeSpyroState(state..4), then hard-resets the anim state machine — sets g_bSpyroAnimCurrent (current anim) to &g_abSpyroStateAnimIndexMap[g_nSpyroState] (the state's default anim), frame=1, timer=0, sub-state g_nSpyroAnimMode=0, and collapses g_nSpyroPrevState (prev-state ctx) to g_nSpyroState. Used by callers that need a clean anim restart vs ChangeSpyroState's preserved blending. */
void RestartSpyroAnimWithState(int state);

/* 0x8003fe40: Per-frame Spyro physics integrator + collision march. Consumes the request bitmask g_dwSpyroRequestMask (bit0/1/2 set linear velocity from absolute targets g_anSpyroRequestTargetPos..58; bit3/4/5 set angles 0xc..0xe from g_abSpyroRequestEuler..5e; bit6 selects shifted-value mode; bit8 forces ChangeSpyroState to g_nSpyroRequestState; bit0x200..0x10000 set g_nCameraNextMode/anchor/target-params; bit0x1000 = enemy-locked turning toward g_pScriptedCameraActor+0x46). Divides velocity by g_nFrameStep to per-frame delta, then substep-marches in 0x154-unit segments calling DispatchActorContactAtSphere (collision detect) + CollideSphereWithWorldAndActors (slide) up to 6 retries per substep. Maintains g_anSpyroPrevWorldPos prev-position + g_nSpyroFrameMotionLength distance traveled. */
int AdvanceSpyroPhysics(void);

/* 0x80040f68: Applies this frame's trigger events (g_dwSpyroTriggerEventFlags & mask, the SPYRO_EV_MASK_* values) as state changes: each hit bit costs one g_nSparxHealth and picks its hurt state (SPYRO_ST_HURT / HURT_PINNED / HURT_TINT / HURT_LONG / KNOCKBACK / KNOCKBACK_2, or DEATH / DEATH_PINNED once the health runs out); SPYRO_EV_HAZARD enters SPYRO_ST_HAZARD, SPYRO_EV_LIFT SPYRO_ST_LIFT, SPYRO_EV_CHARGE_HOLD latches g_nSpyroChargeHoldFlag and SPYRO_EV_REBOUND bounces Spyro off g_anSpyroFirstContactNormal. Returns nonzero when the state changed; UpdateSpyroStateBehavior's cases call it first and bail on nonzero. */
int DispatchSpyroPadStateChanges(int pad);

/* 0x80041270: The charge states' version of DispatchSpyroPadStateChanges (SPYRO_ST_CHARGE, and CHARGE_AIR unless entered from a supercharge). The two contact bits matter here: SPYRO_EV_CONTACT_FRONT bonks (SPYRO_ST_CHARGE_BONK) when the contact actor is ahead of Spyro's body yaw (ArcTan2 within +-0x1FF), SPYRO_EV_CONTACT bonks anyway, and both together (SPYRO_EV_CHARGE_HIT) hurt; the other events are applied as in DispatchSpyroPadStateChanges. */
int DispatchSpyroChargeStateChanges(void);

/* 0x80041558: Idle-animation cycler: advances g_nSpyroIdleAnimSeqCursor (wrap 9) through g_anSpyroIdleAnimStateSeq looking for the next idle-fidget state whose anim record has a nonzero mesh callback (state -> g_abSpyroStateAnimIndexMap -> g_apActorMeshTable[+0x38]). Calls ChangeSpyroState to that state ID. If a full lap finds none, sets g_nSpyroIdleAnimTimeout = 10000 (re-idle later). Triggered from SPYRO_ST_IDLE of UpdateSpyroStateBehavior when the state timer exceeds g_nSpyroIdleAnimTimeout. */
void CycleSpyroIdleAnim(void);

/* 0x80041670: Per-frame Spyro state exits: a switch over all SPYRO_STATE_COUNT SpyroState values. Each case first applies the trigger events (DispatchSpyroPadStateChanges, or the charge variant) and bails if they changed the state, then tests its own exits (pad bits, speed, airborne frames, slope, timers) and calls ChangeSpyroState. Called by TickSpyroGameplayFrame. */
void UpdateSpyroStateBehavior(void);

/* 0x80043fe4: Per-substep Spyro motion integrator. Called g_nFrameStep times per frame from AdvanceSpyroFrameMotion / TickSpyroFrameGlideHold / TickSpyroFrameNoInput; substep = substep index. Sets g_pPadSubstepState = per-substep pad-input record (&g_anPadSubstepRing + idx*0x18). switch(g_nSpyroState) drives per-state motion routines: walk/run cluster → ComputeSpyroMoveTargetFromPad + ApplyPadInputToSpyroBodyYaw + TurnSpyroTowardMoveTargetWithLean + AdvanceSpyroSpeedTowardTarget + BuildSpyroVelocityFromBodyEuler; flame/glide/jump → IntegrateSpyroBodyEuler + BuildSpyroVelocityFromBodyEuler; charge inner switch on g_nSpyroSubstate (charge-substate). Accumulates g_anSpyroVelocity (velocity this substep) into g_anSpyroVelocityFp6 (frame motion accumulator). Updates byte Euler snapshots at g_abSpyroPersistentEuler/65/66. */
void IntegrateSpyroMotionForSubstep(int substep);

/* 0x80047b60: Per-substep physics for the current SpyroState: each state runs its own mix of AverageSpyroPlatformMotion (grounded states), AdvanceSpyroPhysics, ProbeSpyroGroundContact, slope gravity (ApplyGravityAlongSpyroSlopeNormal / Tangent), StepSpyroOntoLocalFloor and ProbeSpyroLedgeForward. Walking states derive the slope-adjusted g_nSpyroMoveTargetMag; the fall and glide states track g_nSpyroFloorReferenceZ for fall damage (kept while g_nSpyroFlightMode); SPYRO_ST_HAZARD sinks Spyro by g_nSpyroHazardSinkDepth and records g_nSpyroHazardFloorZ; SPYRO_ST_SUPERCHARGE emits its trail particles. Called per substep from AdvanceSpyroFrameMotion. */
void DispatchSpyroPhysicsByState(void);

/* 0x8004888c: Per-substep attitude + anim-rate step for the current SpyroState: SPYRO_ST_FALL damps the free-fall attitude (DampenSpyroFreeFallAttitude), SPYRO_ST_CHARGE_AIR aligns the body to the velocity (AlignSpyroBodyToVelocity), and the other ground and air states run UpdateSpyroFlightAttitudeNearGround (SPYRO_ST_SUPERCHARGE only while grounded). WALK, JUMP, SLIDE and JOG scale g_nSpyroAnimPlayRate from g_nSpyroMotionSpeed; a WALK at speed 0 with camera option 0x10 requests camera mode 0x80000000. Always ends with g_nSpyroStateTimer++. Called per substep from AdvanceSpyroFrameMotion, after DispatchSpyroPhysicsByState. */
void AdvanceSpyroSubstepState(void);

/* 0x80048b9c: Per-frame Spyro physics + footstep audio driver. Zeros g_anSpyroVelocityFp6 motion accumulator, loops g_nFrameStep times calling IntegrateSpyroMotionForSubstep(substep_idx), then DispatchSpyroPhysicsByState (footing-state — includes AdvanceSpyroPhysics collision march), then loops g_nFrameStep times calling AdvanceSpyroSubstepState (per-substep finalize). Computes g_nSpyroGroundHeightZ = local ground height via FindGroundHeightBelow, and triggers footstep SFX via DispatchSpyroTriggerEvent gated on g_nGroundSurfaceType step counter + g_nSpyroFirstContactChunkId surface-type. Skips footstep audio if g_dwSpyroRequestMask bit 0x4000 set. Called only by TickSpyroGameplayFrame. */
void AdvanceSpyroFrameMotion(void);

/* 0x80048d10: Per-tick Spyro attack-effects driver — two independent subsystems sharing the function. (1) Superflame glow: while g_nSpyroSuperflameTimer > 0 spawns random-offset particle (1,0x1e) behind Spyro via g_pfnLevelEmitParticles, sets Spyro's red tint g_abSpyroTintRgba (0x90,0x20,0x10) + sinusoidal alpha pulse, blinking for the last 0x78 frames; timer decrements by g_nFrameStep. (2) Flame breath: when g_bSpyroFlameActive, arms flame slots through the g_abSpyroFlameSlotMap permutation, recomputes g_anSpyroFlameAnchorPos (static or body-frame per g_bSpyroFlameAnchorMode, matrix copied to g_anSpyroFlameAnchorMtx), then per slot walks the arc point at its age: DispatchActorContactAtSphere(radius 0xa0) + CastRayWorldAndActors from g_anSpyroFlameSlotPrevPos; on hit freezes the slot (state 2, clip age saved) + spawns a 3-particle burst + SFX_ATTACK_HIT; on arc-end without hit spawns the g_anSpyroFlameEndBurstDirs burst. steps = frame delta. Called from TickSpyroGameplayFrame and SaveMenu_Update. */
void TickSpyroAttackEffects(int steps);

/* 0x800495d8: Anim-layer-1 sub-frame advance: g_abSpyroAnimLayer1SubstepBlock += step; on overflow >= 0x10 wraps and advances g_bSpyroAnimLayer1Frame (frame) by 1, snapshots g_bSpyroAnimLayer1Current → g_bSpyroAnimLayer1Prev and g_bSpyroAnimLayer1Frame → g_bSpyroAnimLayer1FramePrev. Caps frame at &g_abSpyroAnimDescTable+0x2[g_bSpyroAnimLayer1Current * 4] (per-anim length). Layer-1 byte set is the flame-breath anim overlay (vs layer-0 g_bSpyro* primary body anim). */
void AdvanceSpyroAnimLayer1Frame(int step);

/* 0x80049660: Per-tick anim-layer-1 state machine — tracks the flame-breath anim overlay. g_nSpyroFlamePhase = layer mode (0=play, 1=mid-blend +2/tick, 2=hard-switch +4/tick). When mode=0 and g_nSpyroFlameState (flame-breath state) matches g_nSpyroFlameLayer1State (last seen): if bf0=0 snapshots primary g_bSpyro* into layer-1 byte set (a72/73/78/79/7d), else AdvanceSpyroAnimLayer1Frame(g_nSpyroFlameAnimRate rate). On state mismatch reads &g_abSpyroFlameTransitionModes[bf0+ac0*2] transition byte (1=blend, 2=hard) and starts that mode. Modes 1/2 finish when g_abSpyroAnimLayer1SubstepBlock > 0xf → AdvanceSpyroAnimLayer1Frame(0) + mode=0. */
void TickSpyroAnimLayer1(void);

/* 0x80049880: Per-tick PD spring of byte-Euler snapshot. Drives g_abSpyroSwingByteEuler/69/6a (smoothed byte Euler) toward targets g_nSpyroSwingEulerTargetX/c00/c04 via accumulators g_anSpyroSwingEulerSpringAccum/18/1c using shortest-path 12-bit angle delta (uVar2 - prev & 0xfff, > 0x800 wrapping). Spring law: accum += (delta<<7 - accum<<4) >> 6 ; prev += accum >> 6. Called every tick by TickSpyroFlameAttack. */
void SmoothSpyroByteEulerSpring(void);

/* 0x800499c0: Per-tick flame-breath (PAD_CIRCLE) state machine on g_nSpyroFlameState (0 idle / 1 breathing). An anim flagged at g_abSpyroAnimDescTable+0xB8 cancels it. A fresh Circle press while no flame is live starts a breath (g_bSpyroFlameActive = 1, phase/segment reset, random ring base, g_nSpyroFlameVariant = 1 while the superflame timer runs, slot ages cleared); every 4th frame of timer 0xC..0x1C (CD idle) it spawns flame particles at the two g_anSpyroFlameTipOffsets mouth points; another press after 0x2C chains a second breath; at 0x30 it ends. Always ends with SmoothSpyroByteEulerSpring(). */
void TickSpyroFlameAttack(void);

/* 0x80049dfc: Anim-layer-2 sub-frame advance: g_bSpyroAnimLayer2Substep += step; on overflow >= 0x10 wraps and advances g_bSpyroAnimLayer2Frame (frame), snapshots g_bSpyroAnimLayer2Current → g_bSpyroAnimLayer2Prev and g_bSpyroAnimLayer2Frame → g_bSpyroAnimLayer2FramePrev. Wraps to &g_abSpyroAnimDescTable[anim*4] (start frame) when frame hits &g_abSpyroAnimDescTable+0x1[anim*4] (end+1). Layer-2 byte set at g_bSpyroAnimLayer2Prev/75/7a/7b/7e. */
void AdvanceSpyroAnimLayer2Frame(int step);

/* 0x80049e8c: Per-tick anim-layer-2 state machine (analogous to TickSpyroAnimLayer1 but for the second overlay). Only ticks when g_nSpyroAnimLayer2Phase == 0 (layer-2 enabled) AND g_nSpyroAnimLayer2Request == g_nSpyroAnimLayer2Active (state stable). If g_nSpyroAnimLayer2Request == 0 snapshots primary g_bSpyro* into layer-2 byte set (a74/75/7a/7b/7e); else AdvanceSpyroAnimLayer2Frame(g_nSpyroAnimLayer2Rate rate). g_nSpyroAnimLayer2Request is forcibly zeroed by TickSpyroAnimLayer2GateTimer when primary anims block layer 2. */
void TickSpyroAnimLayer2(void);

/* 0x80049f3c: Layer-2 gate timer. If &g_abSpyroAnimDescTable+0xB8[g_bSpyroAnimPrev] == 0 AND &g_abSpyroAnimDescTable+0xB8[g_bSpyroAnimCurrent] == 0 (primary anims permit layer-2 overlay): g_nSpyroAnimLayer2GateFrames++ (frame counter of permissive duration). Else: g_nSpyroAnimLayer2Request = 0 (force-cancel layer-2 active anim). &g_abSpyroAnimDescTable+0xB8 is the per-anim layer-2-blockage flag table — non-zero means the primary anim takes over the bodypart. */
void TickSpyroAnimLayer2GateTimer(void);

/* 0x80049fac: Per-tick Spyro shadow-ring sampler. Computes the shadow center (local (0,0,-0x164) through g_anSpyroBodyMtx + g_anSpyroWorldPos) into g_anSpyroShadowPos with Z = g_nSpyroGroundHeightZ. Refreshes g_bSpyroOtBinBias (5 while < 0x7f), g_nSpyroShadowOtBinBias (3, or 5 when Spyro > 0x364 above ground) and g_nSpyroShadowHiddenFlag (ground <= g_anLevelDeathPlaneZTable[g_nLevelIndex] or trigger event active). Then advances g_nSpyroShadowRingIndex (&7) and samples ONE probe vertex per tick: g_anSpyroShadowProbeOffsetTable entry through the body matrix, +0x200 Z headroom, FindGroundHeightBelow(pt, 0x400); ground within 0x100 of expected writes g_abSpyroShadowRingHeights[idx] = (shadowZ - ground)*0xc2>>9, else sets g_abSpyroShadowRingNoGroundFlags[idx]. probe == 0 skips probing and clears both slots. Output consumed by DrawSpyroDropShadow. */
void SampleSpyroShadowRingHeights(int probe);

/* 0x8004a200: Main per-frame Spyro tick — gameplay entry. Called from GamestateUpdate, CameraSettle_Update, DragonRescue_Update. Order: (1) handle g_dwSpyroRequestMask bits 0x2000 (pause input) + 0x100 (suppress state-machine), (2) AdvanceSpyroFrameMotion (physics + footing), (3) UpdateSpyroStateBehavior (state transitions) unless suppressed, (4) per-substep TickSpyroAnimStateMachine + 4 actor ticks TickSpyroFlameAttack/9660/9f3c/9e8c, (5) build body rotation matrices g_anSpyroBodyMtx + g_anSpyroComposedBodyMtx, (6) SampleSpyroShadowRingHeights/8004d8d10 actor-pose finalize, (7) clears g_dwSpyroTriggerEventFlags pad latch, (8) death/respawn arbiter: out-of-bounds → ChangeSpyroState 6/cam scripted-view → TriggerRespawnOrGameOver, (9) per-frame footstep SFX from g_bSpyroFramePrev/78 anim frames. */
void TickSpyroGameplayFrame(void);

/* 0x8004a7ec: Spyro frame tick that holds a frozen glide (SPYRO_ST_GLIDE, SPYRO_SUB_GLIDE_HOLD; formerly TickSpyroFrameForceJump). Called from LevelLoad_Update (post-level-load intro). Snapshots g_dwPadPressed into g_dwPadStash, forces ChangeSpyroState(SPYRO_ST_GLIDE) if not already there, sets g_nSpyroSubstate=8 (disable charge), then per-substep IntegrateSpyroMotionForSubstep → RShift+Add to position g_anSpyroWorldPos → AdvanceSpyroSubstepState → TickSpyroAnimStateMachine + 4 actor ticks. Builds Euler rotation matrices. Skips footing probe and ground-snap collision (no DispatchSpyroPhysicsByState/d5ec/56f64 calls) — Spyro just flies wherever scripting puts him. */
void TickSpyroFrameGlideHold(void);

/* 0x8004aa0c: Spyro frame tick — no player input, no state-machine. Called from SpyroStateDelay_Update. Same structure as TickSpyroFrameGlideHold but does NOT force a state (only sets g_nSpyroSubstate=8 if already jumping). Per-substep IntegrateSpyroMotionForSubstep + position-step + AdvanceSpyroSubstepState + TickSpyroAnimStateMachine + actor ticks. Used during scripted post-state delays where Spyro coasts visually without responding to pad or transitions. */
void TickSpyroFrameNoInput(void);

/* 0x8004ac24: Reset Spyro entity state. State 7 → clear high byte of g_abSpyroTintRgba. States 0xb/0xf/0x20/0x2c → StopSoundVoicesByOwner(audio reset). full==0 = soft reset (clear input/charge flags g_abSpyroTintRgba/84/88/ca4/ca8/cac/bc0 + rebuild g_nSpyroBodyPitch/78/74 from byte Euler snapshots). full!=0 = hard reset: save pos+euler+g_nSparxHealth, FillWord(g_anSpyroWorldPos, 0, 0x2a4) wiping the whole Spyro state block, restore saved fields, ChangeSpyroState(SPYRO_ST_IDLE). Always sets g_nSpyroFirstContactChunkId=0xff (sentinel surface-type) and g_nSpyroSuperflameTimer=0. Called from BeginCreditsSequence/BeginPauseToMenuTransition/EndDragonRescueToWorld/EndSaveMenuToWorld/LevelIntro_Update/StoryIntro_Update/HandleLevelSelectInput/DragonRescue_Update + level loader BuildLoadedLevelRuntime. */
#ifndef RESET_SPYRO_SOFT
#define RESET_SPYRO_SOFT 0 /* clears input/charge flags, rebuilds body angles */
#define RESET_SPYRO_FULL 1 /* wipes the Spyro block (keeps pos, euler, Sparx), state IDLE */
#endif
void ResetSpyroEntity(int full);

/* 0x8004ae38: Ray cast against world geometry + dynamic actor meshes. Args: ray-start (vec3), ray-end (vec3), unused, scratch buffer. Walks the 4-cell actor grid at g_pActorSpatialGridBase+0x1000 (testing each actor's local-frame mesh via the per-actor-mesh table at &g_apActorMeshTable[idx]+0x38) and the world-chunk index at g_pWorldCollisionHeader. On hit writes: g_anCollisionResolvedPos..b88 = hit point, g_anCollisionProbeVec..70 = hit normal (or surface vector), g_pCollisionHitActor = hit actor ptr (NULL = world hit), g_nLastCollisionHitChunkId = hit triangle index (-1 = actor hit). Returns 1 on hit, 0 otherwise. Shared by every M05 line probe (LedgeForward / GroundContact / OntoLocalFloor / WallProbes) and M06 CheckLineOfSightSegment. */
int CastRayWorldAndActors(int *start, int *end);

/* 0x8004be4c: Sphere-vs-world+actors collision with slide-out resolution. Args: sphere center, radius, max-slide-distance, scratch. Same 4-cell actor grid + world-chunk-index iteration as CastRayWorldAndActors but tests sphere against each triangle: AABB reject, signed dot-product front-face test, then ray-triangle barycentric for closest point. On contact, computes penetration via g_anSqrtLUT iterative refinement and writes pushed-out sphere center to g_anCollisionResolvedPos..b88 + contact point to g_anCollisionContactPoint..60 + normal to g_anCollisionProbeVec..70 + hit actor/triangle. Returns 1 on hit. Callers: AdvanceSpyroPhysics (per-substep collision march, up to 6 retries), DispatchSpyroPhysicsByState (the SPYRO_ST_FLY states' crash test), UpdateGameplayCamera (camera-vs-world collision). */
int CollideSphereWithWorldAndActors(int *pos, int r1, int r2);

/* 0x8004d5ec: Finds the highest world+actor triangle below a point within search distance. Args: position (vec3), max-search-down. Iterates 4-cell actor grid + world chunk index, testing each candidate triangle for XY-containment and reading its Y at the projected point. Tracks highest hit so far in DAT_1f800020. On result writes g_anCollisionResolvedPos..b88 (hit point), g_anCollisionProbeVec..70 (normal), g_pCollisionHitActor (actor or NULL=world), g_nLastCollisionHitChunkId (triangle), g_nGroundSurfaceType (per-triangle surface-type byte). Return value (via g_nCollisionResolvedZ + v0) is the ground Y the caller uses for foot height. Callers: AdvanceSpyroFrameMotion (per-frame foot probe via g_nSpyroGroundHeightZ), DispatchSpyroPhysicsByState (swim/state-0xf air probes), IntegrateSpyroMotionForSubstep, SaveMenu_Update, level-loader BuildLoadedLevelRuntime. */
int FindGroundHeightBelow(int *pos, int depth);

/* 0x8004df24: FindWorldFloorBelowPoint — lightweight world-only ground-height probe at a point. Differs from FindGroundHeightBelow: - World chunks only (no actor grid scan). - First-hit early-exit: scans Z-chunks downward one at a time from the input Z chunk; stops as soon as any world triangle satisfying (X,Y)-containment + Y < input.Y is found. - Writes only to g_nWorldFloorVisZone (per-tri surface-type byte); does NOT touch the shared hit-point / hit-normal globals. - Assumes ground Y > 0 — sentinel iVar19==0 doubles as "no hit yet". Returns floor Y (in world units, << 4 of grid units), or 0 + g_nWorldFloorVisZone = -1 on no-hit. Callers: - UpdateCameraFrame (camera-vs-floor — what's the world geometry directly under the camera target). - DragonRescue_Update (snap gem-display pose to local floor). World data layout: same as the other M07 probes — chunk header at g_pWorldCollisionHeader: +0x8 = X-axis ushort index, +0xc = Y/Z combined ushort index, +0x10 = triangle records (stride 0xc, 14-bit grid-quantized vertices), +0x14 = per-triangle surface-type byte array. */
int FindWorldFloorBelowPoint(int *pos);

/* 0x8004e3c8: Actor-only sphere overlap dispatcher (no world). Args: sphere centre, radius, the trigger-event word the touched actor may raise bits in (Spyro passes &g_dwSpyroTriggerEventFlags, actors 0), the Actor.flags hit bits it gets (ACTOR_HIT_* from Spyro's attacks, 0x40000 from thrown actors, 0 for plain movement), the actor to skip (the mover), and a mode. Walks the 4-cell actor grid at g_pActorSpatialGridBase+0x1000 and, for each actor whose bounding sphere overlaps, runs its type's contact handler through a jump table (damage, pickup, push/bounce). Returns the touched actor or 0. Callers: AdvanceSpyroPhysics, TickSpyroAttackEffects and the actor movers (MoveActorByDelta, SteerActorAlongWaypoints, ...). */
int DispatchActorContactAtSphere(int *pos, int radius, int events, int hitBits, Actor *self, int mode);

/* 0x8004eba8: Renders the per-level static-actor mesh list. Stage 1: Z-cull each mesh chunk via gte_rtps_b, building visible-chunk pointer list at &g_pOtDepthBinHead0. Stage 2: project triangle verts through GTE, build 5-bit frustum outcodes, emit POLY_F3 (0x84) / POLY_F4 (0x86) flat prims into the OT bump buffer at g_pPrimBufferWriteCursor. lod = actor mesh index into g_pWorldRenderMeshIndexTable table (or -1 to walk the flat list at g_pWorldRenderMeshChunkArray..+g_nWorldRenderMeshChunkCount*4). viewMtx/worldMtx = camera rot/translate matrices. Called once at the end of DrawPortalsAndStaticActors, and by Gamestate01_09/04_05/Cutscene_Draw. */
void EmitStaticActorMeshList(int zone, MATRIX *viewMtx, MATRIX *worldMtx);

/* 0x8004f000: Fog-cued sibling of EmitStaticActorMeshList. Same two-stage pattern but uses pre-loaded global view matrix (&g_anCameraViewMtx..df4) + model matrix (&g_anWorldToCameraRotMtx..de0), and applies per-vertex depth cueing via gte_dpcs_b using g_dwActorMeshFadeColor fog RGB and g_nFadeProgress. Cued colors are written to scratch buffer &g_apSecondaryEntityList and fed back into the F3/F4 emit loop. Callers: MenuTransition_Draw (world hub) + ActorCutscene_Draw (post-level treasure summary). */
void EmitStaticActorMeshListFogged(void);

/* 0x8004f4bc: Per-actor textured mesh emitter for close-range dynamic actors. Stage 1: Z-cull each mesh chunk via gte_rtps_b. Stage 2: project each triangle, build 5-bit outcode against the custom scissor rect at g_anActorScissorRect..0c (set by DrawPortalsAndStaticActors per-actor from screen-space vert bounds), dispatch to ClipAndEmitActorTriangle. Final drain of the deferred-prim stack at g_pActorDeferredTriStackTop/&g_anActorDeferredTriStack. mesh = actor mesh struct (size+vertList). viewMtx/outMtx = view/model matrices. Caller: DrawPortalsAndStaticActors close-no-fog path (depth < 0x3001). */
void EmitDynamicActorMeshScissored(int *mesh, MATRIX *viewMtx, MATRIX *outMtx);

/* 0x8004f7e8: Per-triangle clip-and-emit helper for EmitDynamicActorMeshScissored. Builds a 6-bit visibility code from 3 gte_nclip signed-area tests (one per edge) + the upstream 5-bit frustum outcode, then dispatches the 32-entry UNK_8004f890 jumptable to pick a clip case. Fast path: when in_t2 prim head is empty, writes the triangle directly into the OT bump buffer instead of clipping. */
void ClipAndEmitActorTriangle(void); /* register-convention helper: no C callers */

/* 0x8004fdac: GTE depth-cue color helper for a clipped polygon edge. Loads vertex RGB + fog direction (the fog color in a register) into GTE, runs gte_gpl12 (general-purpose linear interp along edge) followed by gte_dpcs_b (depth-cue single-color) to produce the blended RGB at the clip point. Returns the depth-cued color packed with POLY_F2 prim code (0x30000000). No direct callers: invoked exclusively via the UNK_8004f890 / UNK_80050028 clip jumptables from ClipAndEmit{Actor,FoggedActor}Triangle. */
unsigned int BlendDepthCuedEdgeColor(void); /* register-convention helper: no C callers */

/* 0x8004fea0: Fog-cued sibling of EmitDynamicActorMeshScissored. Drives per-triangle ClipAndEmitFoggedActorTriangle over the prim batch set up by the caller. Saves register state (s0-s8, ra, sp, k0) into the GTE backup area at g_anStaticRegSaveArea..e04 so the clip jumptable can read it without reload. Saves/restores g_pPrimBufferWriteCursor OT bump pointer. Reads its triangle list entirely from registers populated by the DrawPortalsAndStaticActors per-actor projection loop — no explicit params. Caller: DrawPortalsAndStaticActors fade-zone path (0x3000 < depth < 0x4000). */
void EmitDynamicActorMeshFogged(unsigned int *color);

/* 0x8004ff90: Per-triangle clip-and-emit helper for EmitDynamicActorMeshFogged. Mirrors ClipAndEmitActorTriangle: 3 gte_nclip tests build a 6-bit visibility code that dispatches the UNK_80050028 fog clip jumptable (32 cases). Fast path: when in_t2 is empty, emits a 5-dword POLY_F4 record into the caller's prim buffer (unaff_s2) and links it via OT head/tail (unaff_s3) without going through the clip jumptable. */
void ClipAndEmitFoggedActorTriangle(void); /* register-convention helper: no C callers */

/* 0x80050240: Fog-shaded sibling of EmitDynamicActorMeshScissored. Mirrors its Z-cull pre-pass over the submesh list (mesh = {count, *list}, viewMtx = world rotation matrix) into &g_pOtDepthBinHead0 survivor list. Stage 2 (uses outMtx = pose matrix) adds a per-vertex gte_dpcs_b color pass over RGB[] (loaded from g_dwActorMeshFadeColor / g_nFadeProgress, writing back into scratch at &g_apSecondaryEntityList) before the gte_rtps_b projection loop; emits screen outcodes against the same scissor at g_anActorScissorRect..0c and dispatches each triangle to ClipAndEmitFogShadedActorTriangle (jumptable UNK_800506b4). Saves GTE backup at g_anStaticRegSaveArea..e04 and advances g_pPrimBufferWriteCursor OT bump pointer. Caller: DrawPortalsAndStaticActors fade-band outline-jittered pass (depth 0x3001..0x3fff) — the per-vertex-dpcs sibling of EmitDynamicActorMeshScissored. */
void EmitDynamicActorMeshFogShaded(int *mesh, MATRIX *viewMtx, MATRIX *outMtx);

/* 0x8005060c: Per-triangle clip-and-emit helper for EmitDynamicActorMeshFogShaded. Mirrors ClipAndEmit{,Fogged}ActorTriangle: 3× gte_nclip on the three SXY's loaded by the caller → 6-bit outcode → dispatches through 32-entry jumptable at UNK_800506b4. Fast direct-emit path (5-dword POLY_F* head/tail) when the prim head is empty; otherwise writes the 7-dword deferred slot into the &g_anActorDeferredTriStack stack at g_pActorDeferredTriStackTop for the caller's drain loop. */
void ClipAndEmitFogShadedActorTriangle(void); /* register-convention helper: no C callers */

/* 0x80050bd0: Render stage 4 (formerly DrawActors). Draws each hub portal in g_apPortals[0..g_nPortalCount] whose vis-zone gate (g_abVisZoneGates) is open: a view matrix rebuilt from the camera euler angles plus the slow g_nPortalViewYawSpin / PitchTilt swirl, the portal's ring projected into g_aMobRingScreenPts, depth-cued (ComputeDepthCuedColor), its silhouette edges built in g_aMobSilhouetteEdges and emitted once as-is and, nearer than 0x4000, once fattened by 2 px. Then emits the static actor meshes (EmitStaticActorMeshList), at LOD -1 (full) unless g_nCameraVisZone is under g_nVisZoneCount. */
void DrawPortalsAndStaticActors(void);

/* 0x800521c0: Visible-entity-list builder (hand-written asm). Walks the actor pool from g_pActorListBase (stride 0x58), reading the word at +0x48: mode byte >= 0x80 (dormant) is skipped and 0xFF ends the pool. The signed renderList byte (+0x4B) picks the list: > 0 the main mesh list at g_pOtDepthBinHead0 (BuildActorDrawList), < 0 (ACTOR_RENDER_SECONDARY) g_apSecondaryDrawEntityList, 0 the sprite queue g_apSpritePrimQueue. An actor whose visZone (+0x4A) is not 0xFF and whose g_abVisZoneGates byte is 0 is taken back off the list and gets drawn = 0. Each list ends with a 0 entry. Called once at the top of every gameplay-frame render chain. */
void BuildRenderEntityLists(void);

/* 0x800522c0: Actor animation tick for an actor-pointer list (mode = frame-step shift). Walks NULL-terminated actor-pointer list at *list, advances per-actor anim subframe at +0x40 by (DAT_1f800000._1_1_ >> mode), wraps to next animation frame when subframe overflows 0x40 (consulting the per-anim length at puVar15[0]), and on key-frame markers (+0x27 sound-trigger byte) queues PlaySoundEffect requests into a small queue at &g_pOtDepthBinHead0 + scratch. After the actor walk, drains the queue calling PlaySoundEffect(soundId, actorPtr, 8, actorPtr+0x54) for each queued trigger. Every level's UpdateActors runs it on g_apActiveActorList (the list BuildActiveActorList writes at g_apActiveActorList), twice on a long frame; SaveMenu_Update runs it on a one-actor list. Drives per-frame actor animation playback and the per-frame sound triggers. */
void TickActorAnims(struct Actor **list, int mode);

/* 0x800524c4: Allocates the next free actor record from the primary (88-byte stride) + aux (0x18 stride) pools. Reads current free-list head g_pActorPoolFreeHead, increments g_nActorPoolLiveCount live count, clears the slot's allocated marker (byte +0x48 = 0), then walks forward 88 bytes at a time skipping mid-pool free markers (0xfe) until it hits either a -1 end sentinel (new free list end at +0x28 = 0xff) or the next free slot. Repeats the same dance for the aux 0x18-byte pool at g_pActorAuxPoolFreeHead. Writes the aux pointer back to primary[0] (the bridge). Result: caller reads the *previous* g_pActorPoolFreeHead value as the freshly-allocated primary slot pointer. Only caller currently: DragonRescue_Update. */
Actor *AllocActorRecordSlot(void);

/* 0x80052568: Frees an actor record: unlinks from spatial-grid cell list at g_pActorSpatialGridBase[actor[0xd]], decrements g_nActorPoolLiveCount live count, marks the primary 88-byte slot freed (byte +0x48 = 0xfd if live-tail / 0xfe if mid-pool / 0xff if new free-list end), then frees the chained 0x18-byte aux record at *actor, and advances free-list heads g_pActorPoolFreeHead (primary) / g_pActorAuxPoolFreeHead (aux) to whichever slot is now the lowest free. The 0xfe/0xff/0xfd markers form a run-length-encoded free bitmap walked by AllocActorRecordSlot. */
void DespawnActorRecord(Actor *actor);

/* 0x800526a8: Per-actor finalize after pose change: looks up anim frame at &g_apActorMeshTable[type_idx]+0x38+state*4+frame*8+0x24, copies prim-type byte to +0x41, copies bound-vector to +0x8 (offset selected by bits 19..20 of anim flags). If mob_table[+0x14]!=0 (collidable), quantizes pos.x/y at +0xc/+0x10 to a 14-bit grid cell index (32-cell-wide grid, bit 0x400 = z-sign), stores it at +0x34 (short), and prepends the actor onto the per-cell linked list at g_pActorSpatialGridBase[cell]. Finally rebuilds a 5-short rotation matrix at +0x20..+0x30 by multiplying X-pitch * Y-yaw * Z-roll using the cos/sin LUTs at &g_anCosineLut / &g_anSineLut — the three byte Eulers live in the high 3 bytes of word +0x44 and each is a 2-byte LUT entry (8-bit angle × 2 = 0..0x1fe). Skips any matrix mult whose angle byte == 0. */
void InsertActorIntoSpatialGrid(Actor *actor);

/* 0x800529cc: Hides an actor: clears prim-type tag bytes at +0x41/+0x4b (preventing render submission), clears the first dword of the bound-vec at +0x8, and writes 0xffff to the spatial-grid cell index at +0x34 (the "not in grid" sentinel). Caller-driven inverse of InsertActorIntoSpatialGrid; does NOT walk the per-cell linked list (the caller is responsible for unlinking, or the actor was never linked). Used by HUD init (UpdateHudCounters' setup pass over the 12 icon slots) and by the M09 level loader to reset stale slots. */
void HideActorRenderRecord(Actor *actor);

/* 0x80052f38 (hand-written): Adds animation `anim`/`sub`'s root-motion step for `frame` (from Spyro's mesh record in g_apActorMeshTable and g_anAnimRootMotionDeltaLut) to the vector `out`. Called twice per substep by IntegrateSpyroMotionForSubstep (body and second layer). */
void AccumulateAnimRootMotionDelta(int frame, int *out, int anim, int sub);

/* 0x800533d0: Encodes the cached probe vector at g_anCollisionProbeVec/6c/70 (X/Y/Z, the collision-system scratch vector written by FindGroundHeightBelow / CastRayWorldAndActors / sphere-probe paths) plus a 14-bit scalar at g_nCollisionResolvedZ into a packed direction code at actor+0x1c. Only re-encodes when bit 31 of the existing field is set (caller flips bit 31 as a "needs recompute" sentinel). Magnitude path: gte_sqr0 on (X,Z), sqrt-LUT lookup at g_anSqrtLUT → 2D XZ-plane magnitude. Then two arctan2 quadrant-decompositions: (XZmag vs Y) → pitch byte angle, (Z vs X) → yaw byte angle (each = quadrant + 5-bit frac, packed to 6 bits via >>2). Output layout: bit 31 set + pitch<<22 + yaw<<16 + (g_nCollisionResolvedZ>>2) in low 14 bits. Callers: BuildLoadedLevelRuntime (level loader, spawn-time encoding), SaveMenu_Update (save-host pan re-encode), DragonRescue_Update (per-frame burst direction). */
void EncodeCachedVecToActorDirCode(Actor *actor);

/* 0x800536a4: Resets the per-substep pad-input distribution table (head + 4 records of 0x18 bytes each). Head: base[0..2]=0, [6]=[7]=1, [5]=0x7f7f7f7f (neutral analog). Per-record (stride 0x18 = 6 dwords): zeroes [0x12/0x13/0x14], preserves [0x11] = base[3] (calibration link), writes [0x16] = 0x7f7f7f7f (neutral analog). Called by MovePadInputState (end-of-frame) and the level-loader BuildLoadedLevelRuntime. */
void ResetPadFrameSubstepTable(int *base);

/* 0x80053708: Moves the 0xA4-byte pad state block (g_dwPadPressed head + 4-record per-substep table) from `from` to `to` (CopyWords), then clears `from` via ResetPadFrameSubstepTable and toggles g_bPadInputStashed. Called in pairs by TickSpyroFrameGlideHold, TickSpyroFrameNoInput, TickSpyroGameplayFrame, UpdateCameraFrame: live -> g_dwPadStash while g_nSpyroInputBlankCountdown runs (Spyro sees no input), and back after the frame. */
void MovePadInputState(void *from, void *to);

/* 0x8005375c: Writes the default uncalibrated 4-axis stick bounds at cal[0x20..0x2b]: each axis gets +0x20=0x7f (neutral), +0x24=0 (low), +0x28=0xff (high) for axes 0..3. Used as the fallback when FinalizePadCalibration detects the controller's reported range is too narrow to trust. Callers: FinalizePadCalibration (fallback path), PollPadAndDistributeInput (init), InitPadSystem. */
void ResetPadStickCalibrationDefaults(unsigned char *cal);

/* 0x80053790: Finalizes per-axis analog calibration after the controller reports its observed lo/mid/hi values. For each of 4 axes: cal[+0x20+i] = recorded neutral, +0x24+i = lo bound, +0x28+i = hi bound. If hi-lo span < 0x30 (controller didn't move enough yet) OR lo-mid distance < 0x30: falls through to ResetPadStickCalibrationDefaults (sets the no-calibration defaults +0x20=0x7f, +0x24=0, +0x28=0xff for all 4) and returns 0. Otherwise: computes lo_mid breakpoint at +0x2c = neutral + '0' (0x30), hi_mid breakpoint at +0x30 = neutral - 0x30, and scaling factors +0x34 = 0x4000 / (hi - lo_mid), +0x3c = 0x3f80 / (lo_mid - lo), then clears the snapshot head (cal[0..2]=0, cal[6]=cal[7]=1, and the 4-byte field at +0x14 of head = 0x7f7f7f7f neutral). Also clears the 4-record per-substep table: each record at +6 dwords stride has [0x12/0x13/0x14] = 0 and +0x58 (= +0x16 of record from caller view) = 0x7f7f7f7f. Returns 1 on success. Callers: PollPadAndDistributeInput, InitPadSystem. */
int FinalizePadCalibration(unsigned char *cal);

/* 0x80053940: Maps raw 8-bit analog stick values into the calibrated 0..0xff range for 4 axes (cal[0..3]). For each axis: if raw < calibration[+0x2c] (mid-low): output = 0x7f + ((raw - low_mid) * scale_low[+0x34]) >> 7, clamped to ≤0xff. If raw > calibration[+0x30] (mid-high): output = 0x7f - ((raw - high_mid) * scale_hi[+0x3c]) >> 7, clamped to ≥0. Else: output = 0x7f (neutral). The two scale factors (+0x34 / +0x3c) and the two mid breakpoints (+0x2c / +0x30) per axis are filled in by FinalizePadCalibration from the controller's reported hi/lo bounds. Callers: SampleDemoPadFrame, PollPadAndDistributeInput. */
void MapPadAxisToCalibratedRange(unsigned char *cal, int block);

/* 0x800539fc: Attract-demo pad sampler (sole caller TickDemoPlayback). Record mode (g_nDemoMode == 2): reads the raw pad (inverted button halfword + calibrated right-stick bytes via MapPadAxisToCalibratedRange) and appends the packed word (buttons | stick<<16) at g_pDemoPadCursor. Playback: reads the next recorded word back instead (left stick centred at 0x7F). Either way rebuilds g_dwPadHeld/Pressed/Released and the stick-active flag, broadcasts to all 4 pad substep records, refreshes the idle flags, sets g_nPadType = 3 and forces g_nFrameTicks = 2 so every demo frame is two vblanks. Returns 2. */
int SampleDemoPadFrame(void);

/* 0x80053c68: Per-VBlank pad poll callback (registered by InitPadSystem via InstallVSyncCallback). Increments g_nVblankTickCount (+ g_nCdStallWatchdogTicks while g_nCdStallMarker set), bails if g_nDemoMode != 0 (the attract demo samples the pad itself in SampleDemoPadFrame). Identifies pad type from g_abPadRawReport (status/id bytes) → g_nPadType (enum PadType: 0 none, 1 unsupported id, 2 digital 0x41, 3 analog 0x73 / 0x53 remapped); on disconnect sets g_nPadSetMainModePending, on state 6 sends PadSetActAlign(g_abPadActAlignTable) → g_nPadActAlignedFlag; PadInfoMode(0,2,0) → g_nPadIsDualshockFlag. Vibration: builds g_abPadActCommand from g_nHitRumbleTimer (motor1 0x78) / g_nVibrationLevel (motor0) / g_nPulseRumbleTimer+Amount, decrements all timers, sends via PadSetAct — all cleared unless g_nOptionVibrationEnabled && DualShock. Input: inverts button shorts, remaps Saturn buttons, MapPadAxisToCalibratedRange → g_dwPadAnalogCalibrated, synthesizes virtual D-pad bits 0x1000-0x8000 from the left stick (g_nPadStickActiveFlag), edge-detects vs g_dwPadHeld, resets (substep 0) or OR-accumulates g_dwPadPressed / g_dwPadReleased, maintains the sticky idle flags g_nPadAllInputIdleFlag / g_nPadDirectionalIdleFlag, and distributes {type, held, pressed, released, stickActive, analog} into g_anPadSubstepRing[g_nFrameTicks*6] (max 4 substeps). Increments g_nFrameTicks. */
void PollPadAndDistributeInput(void);

/* 0x800542e4: Sets a multi-digit decimal counter into HUD icon slots. Splits value into decimal digits, writes them into count slots starting at slot index slot (each slot is a 0x58-byte record at &g_abHudIconActorRecords[slot*0x58]). icon = init/commit flag: when 0, writes only the pending digit byte at +0x35 (used mid-roll-animation); when non-zero, writes the committed glyph UV at +0x22 (= 0x104 + digit, the digit-glyph UV in the HUD tilemap) and forces alpha 0xff at +0x3c. Leading zeros render as glyph 0 unless icon != 0 in which case unused slots get alpha 0. Called by UpdateHudCounters' state-2 path and by the HUD init. */
void SetHudCounterDigits(int slot, int count, int value, int icon);

/* 0x80054400: Per-slot roll-animation offset writer for the big HUD icon records. For count slots starting at base, writes (base + delta) into the +0x14 field of each 0x58-byte icon record at &g_abHudIconActorRecords, where base = (&g_anHudIconRestPos+0x4)[slot*0xc] (= +4 of the per-slot rest-position vec3 at &g_anHudIconRestPos). Sole caller UpdateHudCounters passes ±sine-LUT entries to drive the roll-in/roll-out animation on digit changes. */
void OffsetHudIconRollAxis(int base, int count, int delta);

/* 0x8005445c: Per-slot roll-animation offset writer for the small HUD digit sprite descriptors. For count slots starting at base, writes (base + delta) into the +0x2 (V) field of each 8-byte sprite record at &g_anHudSpriteRects, where base = (&g_anHudDigitRestRects+0x2)[slot*4] (= +0x2 of the per-slot rest UV in &g_anHudDigitRestRects). Sole caller UpdateHudCounters; mirror of OffsetHudIconRollAxis but for the digit-sprite vertex table rather than the big icon records. */
void OffsetHudDigitRollAxis(int base, int count, int delta);

/* 0x800544a8: Commits the per-slot digit-roll animation state byte at +0x32 of each 0x58-byte HUD icon record. For count slots starting at slot: if the slot is already mid-animation (+0x32 != 0) OR its pending glyph at +0x35 differs from its committed glyph at +0x22 (- 0x104 base), writes state as the new state. When state == 0xc0 (end-of-roll commit), also latches +0x22 = pending glyph + 0x104 and forces alpha 0xff. Called by UpdateHudCounters' state-2 path to ratchet the roll animation forward. */
void CommitHudCounterAnimState(int slot, int count, int state);

/* 0x80054600: HUD init for entering gameplay-with-HUD state. Zeros + re-seeds the 12 big-icon records in g_abHudIconActorRecords (HideActorRenderRecord per slot, rest vec3 from g_anHudIconRestPos, default render bytes), copies the 12 rest rects from g_anHudDigitRestRects into g_anHudSpriteRects, sets all five g_abHudCounterDisplayState machines to 1 with phases/timers zeroed, seeds the cached counts (g_nHudLevelGemCachedCount / g_nHudDragonCachedCount / g_nHudLivesCachedCount / g_nHudEggCachedCount / g_nHudKeyCachedState / g_nHudButterflyCachedCount) from the live values, and draws the initial digits via SetHudCounterDigits x3. layout_butterflies != 0 additionally clears g_nHudEggRollRequest and lays out the sparx-food butterflies from g_abHudButterflyRingXY. Callers: EndDragonRescueToWorld, EndSaveMenuToWorld, EnterPauseMenu, BuildLoadedLevelRuntime. */
void InitHudCounters(int layout_butterflies);

/* 0x80054988: Per-frame HUD update. Ticks the five digit-counter state machines in g_abHudCounterDisplayState (0=level gems vs g_anLevelGemsCollected[g_nLevelIndex], 1=dragons rescued, 2=extra lives + sparx food, 3=egg tally vs g_nTotalEggsRecovered — forced visible while g_nHudEggRollRequest is set (by a recovered dragon egg, type 34), 4=the level key vs g_nLevelKeyState). Each machine: state 1 roll-in (g_anHudRollInStepTable), state 2 hold + count-up toward the live value (g_nHud*HoldTimer pacing, sparkle bursts via g_pfnLevelEmitParticles), state 3 roll-out (g_anHudRollOutStepTable); counter 0 adds state 4 = level-complete highlight when cached == g_anLevelTotalGemsTable[level]. Animates icon bob/tint bytes inside g_abHudIconActorRecords from g_anSineLut, lays out one butterfly sprite per food unit into g_anHudSpriteRects, and rolls g_nSparxFoodCount over into +1 extra life at 20. Callers: GamestateUpdate, PauseMenu_Update, EnterPauseMenu. */
void UpdateHudCounters(void);

/* 0x800557cc: Spawns one floating digit actor (id 0x104 + digit) per decimal digit of value, least significant first, walking away from src along the camera yaw (CommitActorKillGems, for kills worth gems above z 0x300). */
void SpawnFloatingDigitActors(int value, Actor *src);

/* 0x8005595c: Top-level music/sound state init called from Initialize after SpuInit. Calls InitSpu (sound channel reset), seeds master volume + CD-DA mix words at g_abSpuCommonAttr..g_nSoundMonoMixFlag, then SetSpuCommonAttr / ApplySpuVoiceAttr / SetSpuKeyMask / SetSpuTransferMode (sound-bank registration), FillWord(g_aSpuVoiceRows, 0, 0x2a0) zeros the channel-state block. Body internals deferred to M10. */
void InitSoundEngine(void);

/* 0x80055a78: Starts sample `sampleId` on a free mixer row owned by `owner`. `mode` is SFX_MODE_FLAT / SFX_MODE_3D (positional; dropped outside owner->soundRange) / SFX_MODE_PANNED; FLAT and 3D refuse to retrigger a sample the owner is already playing. The row index (0x7F when dropped) goes to *pPlaying. */
unsigned int PlaySoundEffect(unsigned int sampleId, Actor *owner, unsigned int mode, unsigned char *pPlaying);

/* 0x80056200: Stops one SPU voice by index. index = voice index (low 7 bits, 0..23). Sets bit index of g_dwSpuPendingKeyOff (pending hardware-keyoff mask), then if mode is 2 or 4: resets the table row at &g_aSpuVoiceRows + (idx*0x1c) — writes 0x7f to the busy-marker via the writeback pointer at +0x18, zeros owner-key +0x00 + writeback ptr +0x18 + interp delta +0x14, sets flags ushort +0x0e=0x40 (idle), sets byte +0x0d=0xff (alignment). The 24-entry × 0x1c table at &g_aSpuVoiceRows holds per-voice runtime state. Sole caller: DragonRescue_Update. */
void StopSoundVoiceByIndex(int index, int mode);

/* 0x800562a4: Stops all SPU voices whose owner-key at +0x00 matches actor. Walks all 24 voice rows at &g_aSpuVoiceRows (stride 0x1c); for each match: kills the voice (resets row to idle as in StopSoundVoiceByIndex) when mode==1, or when mode==2 AND the looping flag (bit 0x100 of flags +0x0e) is set. OR's the kill bitmask into g_dwSpuPendingKeyOff at end. Callers: ChangeSpyroState (stops all Spyro-owned voices on state change), ResetSpyroEntity (full-stop on respawn/level-load). */
void StopSoundVoicesByOwner(Actor *actor, int mode);

/* 0x8005637c: Per-frame SPU voice mixer tick — walks all 24 voice rows at &g_aSpuVoiceRows (stride 0x1c). For each active voice (flags bit 0x1, mask 0x40 idle clear): queries hardware state via GetSpuVoiceKeyStatus (SpuGetKeyStatus equiv) and dispatches on flags 0x1c mode group. Mode 8 (3D positional): subtracts source pos from camera at g_anCameraPos, computes distance via VectorLength, ArcTan2 vs camera yaw g_nCameraEulerYaw, calls ComputeVoicePanAndFalloff for 3D pan, attenuates with 1/r² falloff over the per-voice range at owner+0x55 (defaults 0x4000 when 0), reuses cached vol/pan via SpuGetVoiceVolume when out-of-range. Mode 4: defaults vol to 0x2000. Mode 0x10: holds last vol/pan. Always multiplies final by master vol g_nSoundMasterVolume (>>0xc), advances per-voice interp counters +0x14/+0x18, issues SPU update via ApplySpuVoiceAttr (SpuSetVoiceVolume). On hardware status indicating natural-end (GetSpuVoiceKeyStatus returns 1 or 3 + flag bit 0x2 set): kills the row and ORs bit into g_dwSpuPendingKeyOff. Callers: CdReadSyncSectors, GamestateUpdate. */
int TickActiveSoundVoices(void);

/* 0x800567f4: XA music command dispatcher (libcd). cmd = MUSIC_CMD_* (cd_music.h): 1 = play track track (uses sector at g_anMusicTrackLbaTable + track*8); 2 or 4 = stop streaming (sets state machine via g_nPendingMusicCommand to fade/pause); 8 = resume streaming from saved sector g_dwCdMusicReadHead. Play path issues CdlSetmode(0x0e, 0xc8) + CdlSetfilter(0x0d) + CdlReadS(0x1b) (XA-stream read). Short-circuits when mute bit (g_dwMusicStreamStatus & 0x80) is set; falls through to "stop" path if music volume is 0 or 0x40 state bit not set. Used by game-state transitions (level/cutscene boundaries) and StopAllSoundExceptMask. */
void HandleMusicCommand(int track, int cmd);

/* 0x80056b28: Mass voice-stop helper used for state transitions. Walks all 24 SPU voice rows at &g_aSpuVoiceRows: for any active voice (flags +0x0e bits 0x83 set — bit 0x1=active or bit 0x2=playing) NOT in mask mask, stamps owner's per-mode busy-flag byte (offset +0x54 for mode-8 / +0x2a0 for mode-4) with 0x7f=released, ORs voice idx bit into g_dwSpuPendingKeyOff (pending hardware keyoff mask consumed by SPU update), zeros voice row (owner ptr / interp delta / writeback ptr), sets flags=0x40 (idle). After the walk, zeros g_dwSpuPendingKeyOn and calls HandleMusicCommand(0, 4) to stop CD music. Common callers (mask=0 → "kill everything"): pause-menu enter, level-cutscene begin, death plane, credits sequence. */
void StopAllSoundExceptMask(int mask);

/* 0x80056c84: 3D positional sound pan + distance falloff. Inputs: vol=&out[L,R] shorts, dist=squared-distance vol scalar, bearing=pan byte (0x80=center; wraps full-L/full-R via the 0x40/0xbf compare), range=range (divisor; returns early if 0), cached=listener-relative baseline [L,R]. Computes falloff fraction (dist<<8)/range, derives per-channel gains, applies to baseline, clamps each to [0,0x3fff]. If mono-mix flag g_nSoundMonoMixFlag set, averages L=R. Called by PlaySoundEffect (one-shot trigger pan) + TickActiveSoundVoices (per-frame mode-8 voices). */
void ComputeVoicePanAndFalloff(short *vol, int dist, unsigned char bearing, unsigned int range, short *cached);

/* 0x80056dc4: Looks up the SPU voice currently playing for a given (owner-key, marker-byte) pair. Walks all 24 voice rows at &g_aSpuVoiceRows matching (actor == row+0x00 = owner-key) AND (a == row+0x0d = marker). Returns: 0 = no match (sound not playing for this owner/marker); 1 = found, one-shot (flags +0x0e bit 0x100 clear); 2 = found, looping (flags +0x0e bit 0x100 set). Sole caller: PlaySoundEffect (used to skip re-triggering an already-playing sound). */
int GetSoundVoiceStatusByOwner(Actor *actor, int sampleId);

/* 0x80056e3c: Reconciles software voice state with hardware. Probes the SPU via GetAllSpuVoiceKeyStatus into a 24-byte local buffer; for any voice whose hardware status code is 1 (SPU_ON) but whose software flags +0x0e have neither bit 0x1 (active) nor bit 0x40 (idle) set (i.e., software thinks the row is stale), marks the row idle (flags=0x40) and ORs the bit into g_dwSpuPendingKeyOff (pending hardware-keyoff mask consumed by SetSpuKeyMask). Sole caller: TickSpuPerFrame (runs once every 64 frames via g_dwGamestateFrames & 0x3f). */
void SyncSoundVoicesWithHardware(void);

/* 0x80056ed4: Per-frame SPU update tick. Every 64 frames (g_dwGamestateFrames & 0x3f == 0) runs SyncSoundVoicesWithHardware to reconcile drift. Then drains the two pending hardware-key masks: if g_dwSpuPendingKeyOn (pending keyon mask) != 0, calls SetSpuKeyMask(1, mask) and clears it; if g_dwSpuPendingKeyOff (pending keyoff mask) != 0, calls SetSpuKeyMask(0, mask) and clears it. Callers: GamestateUpdate + every per-state Update that may set/clear voices (PauseMenu_Update, Cutscene_Update, etc.). */
void TickSpuPerFrame(void);

/* 0x80056f64: Fires trigger region `idx` for `event` (1 enter, 2 inside): the region's TriggerRegionType picks hazard / lift / ground latch / charge-hold / rebound / damage event bits, or a portal warp. */
void DispatchSpyroTriggerEvent(int idx, int event);

/* 0x800573c8: Emit-list rasterizer (hand-asm GTE core; saves s-regs to scratchpad 1f800000, gp anchor g_abSpyroFlameTransitionModes). Walks the per-level particle/billboard emit list at g_pEmitListBase: linear 0x20-byte records, capacity 0x2000 (256 records), list empty when a record's opcode byte is 0xff (loader seeds this; DragonRescue_Update resets it during the rescue cutscene; records are appended by overlay code via g_pfnLevelEmitParticles). RECORD FORMAT: +0 short header {lo byte = index into g_apMobEntryTable (texture source), hi byte = opcode; hi<0 = skip record, 0xff = end}; +3 byte = written back each frame (1 = prim emitted, 0 = culled) so game logic can poll visibility; +4/+8 packed world pos (x,y,z halfwords, transformed camera-relative via g_anCameraPos>>2 and g_anWorldToCameraRotMtx); for opcodes 2/5/6+: +8 bits 16-23 = brightness (IR0), bits 23+ = spin phase into g_anSineLut; +0xc = packed RGB/mode color word; +0x10 ushort {lo = 8-byte sub-record index into the mob's table (+4/+8 = texpage/UV words), hi = OT depth-bin bias subtracted from sz>>5}; +0x14 = texword for flat opcodes. OPCODES: 0 = 1px line dot (0x03-len prim), 1/4 = flat 2-vert prim (0x04-len; 4 = absolute-pos variant via gte_ldtr), 2 = lit spinning billboard quad, 3 = alt-lit billboard, 5 = depth-faded spinning billboard, 6+ = default spinning billboard (all 0x09-len POLY_FT4, 0x28 bytes). Links prims into g_pOtDepthBinArrayBase bins; bails with g_nPrimBufferOverflowFlag=1 at g_pPrimBufferLimit-0x400. */
void RasterizeEmitList(void);

/* 0x800580f4 (hand-written): Projects and emits the world sparkle particles in g_abWorldSparkleParticleTable into the OT at g_pPrimBufferWriteCursor. First half of DrawWorldParticleEmitters. */
void DrawWorldSparkleParticles(void);

/* 0x800584c4 (hand-written): Ages by `frameStep`, projects and emits the rotating billboards in g_aRotBillboards (SpawnActorRotBillboard). Second half of DrawWorldParticleEmitters. */
void DrawWorldRotatingBillboards(int frameStep);

/* 0x80058864: Dragon-rescue aura emitter — 8-pointed semitransparent star burst billboard around the gem position. Loads view matrix at g_anWorldToCameraRotMtx..de0, computes camera-relative anchor (g_anDragonRescueAuraStarAnchor/dfc/e00 minus camera g_anCameraPos/250/254), then loads billboard rotation matrix at g_anDragonRescueAuraStarMtx..68 (filled by ApplyEulerRotation from byte-angles at g_abDragonRescueAuraStarEuler by caller). Projects center vertex + 8 inner-ring verts (radius scale = g_nDragonRescueAuraStarRadius >> 0xc, angles from sin/cos LUTs at &g_anSineLut/&g_anCosineLut stride 0x40 = 45°) + 8 outer-ring verts (radius 4x larger via >> 0xa, angles offset by 22.5°). Inner ring is closed (vertex[0] = vertex[N]). Emits drawmode prim (0xe1000620 untextured + 0x2000000 semi-trans), then loops 8 times emitting 2 POLY_F3 per slice: outer-spike triangle (inner[i], inner[i+1], outer[i]) + inner-fan triangle (inner[i], inner[i+1], center) for 16 triangles total. Color byte applied to all 6 color slots from g_bDragonRescueAuraStarColor. Each prim inserts into OT via g_pOtActiveDepthSlot head-ptr. Sole caller: DragonRescue_Draw, conditional on g_nDragonRescueAuraStarEnabled trigger flag. */
void DrawDragonRescueAuraStar(void);

/* 0x80058b68: Resets the world particle/billboard tables on level load. Zeroes the 16-entry x 0x24-byte emitter array at &g_abWorldSparkleParticleTable (used by DrawWorldParticleEmitters/DrawWorldSparkleParticles) and the 8-entry x 0x18-byte billboard array at &g_abWorldRotatingBillboardTable (used by DrawWorldRotatingBillboards). Sole caller BuildLoadedLevelRuntime (level loader meat). */
void ResetWorldParticleTables(void);

